#include "util.h"

#include <errno.h>
#include <fcntl.h>
#include <sched.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include <algorithm>
#include <chrono>
#include <fstream>
#include <sstream>

void Fatal(const char* msg, ...) {
  va_list ap;
  fprintf(stderr, "ninja: fatal: ");
  va_start(ap, msg);
  vfprintf(stderr, msg, ap);
  va_end(ap);
  fprintf(stderr, "\n");
  // Exit without running destructors; this mirrors a hard failure.
  fflush(stdout);
  exit(1);
}

void WarningV(const char* msg, va_list ap) {
  fprintf(stderr, "ninja: warning: ");
  vfprintf(stderr, msg, ap);
  fprintf(stderr, "\n");
}

void Warning(const char* msg, ...) {
  va_list ap;
  va_start(ap, msg);
  WarningV(msg, ap);
  va_end(ap);
}

void ErrorV(const char* msg, va_list ap) {
  fprintf(stderr, "ninja: error: ");
  vfprintf(stderr, msg, ap);
  fprintf(stderr, "\n");
}

void Error(const char* msg, ...) {
  va_list ap;
  va_start(ap, msg);
  ErrorV(msg, ap);
  va_end(ap);
}

void InfoV(const char* msg, va_list ap) {
  fprintf(stdout, "ninja: ");
  vfprintf(stdout, msg, ap);
  fprintf(stdout, "\n");
}

void Info(const char* msg, ...) {
  va_list ap;
  va_start(ap, msg);
  InfoV(msg, ap);
  va_end(ap);
}

void CanonicalizePath(std::string* path, uint64_t* slash_bits) {
  size_t len = path->size();
  if (len == 0) {
    *slash_bits = 0;
    return;
  }
  char* p = &(*path)[0];
  CanonicalizePath(p, &len, slash_bits);
  path->resize(len);
}

static inline bool IsSep(char c) { return c == '/'; }

void CanonicalizePath(char* path, size_t* len, uint64_t* slash_bits) {
  *slash_bits = 0;
  if (*len == 0)
    return;

  char* start = path;
  char* dst = start;
  char* dst_start = dst;
  const char* src = start;
  const char* end = start + *len;

  if (IsSep(*src)) {
    // Absolute path: the leading separator is always kept.
    ++src;
    ++dst;
    dst_start = dst;
  } else {
    // Leading "../" components are copied verbatim.
    while (src + 3 <= end && src[0] == '.' && src[1] == '.' && IsSep(src[2])) {
      src += 3;
      dst += 3;
    }
  }

  int components = 0;
  char* base = dst;  // lowest point we may back up to
  const char* src_next = nullptr;
  for (; src < end; src = src_next) {
    const char* sep =
        static_cast<const char*>(memchr(src, '/', end - src));
    if (!sep)
      break;  // last component handled below
    src_next = sep + 1;
    size_t clen = sep - src;
    if (clen <= 2) {
      if (clen == 0)
        continue;  // "//"
      if (src[0] == '.') {
        if (clen == 1)
          continue;  // "./"
        if (src[1] == '.') {
          if (components > 0) {
            --components;
            while (--dst > base && !IsSep(dst[-1])) {
            }
          } else {
            dst[0] = '.';
            dst[1] = '.';
            dst[2] = src[2];
            dst += 3;
          }
          continue;
        }
      }
    }
    ++components;
    if (dst != src)
      memmove(dst, src, src_next - src);
    dst += src_next - src;
  }

  size_t clen = end - src;
  do {
    if (clen == 0)
      break;
    if (src[0] == '.') {
      if (clen == 1)
        break;
      if (src[1] == '.' && clen == 2) {
        if (components > 0) {
          while (--dst > base && !IsSep(dst[-1])) {
          }
        } else {
          dst[0] = '.';
          dst[1] = '.';
          dst += 2;
        }
        break;
      }
    }
    if (dst != src)
      memmove(dst, src, clen);
    dst += clen;
  } while (0);

  if (dst > dst_start && IsSep(dst[-1]))
    dst--;

  if (dst == start)
    *dst++ = '.';

  *len = dst - start;
}

static bool IsShellSafe(char ch) {
  if ('A' <= ch && ch <= 'Z') return true;
  if ('a' <= ch && ch <= 'z') return true;
  if ('0' <= ch && ch <= '9') return true;
  switch (ch) {
    case '_':
    case '+':
    case '-':
    case '.':
    case '/':
      return true;
    default:
      return false;
  }
}

void GetShellEscapedString(const std::string& input, std::string* result) {
  bool needs = false;
  for (char c : input) {
    if (!IsShellSafe(c)) {
      needs = true;
      break;
    }
  }
  if (!needs) {
    result->append(input);
    return;
  }
  result->push_back('\'');
  size_t span = 0;
  for (size_t i = 0; i < input.size(); ++i) {
    if (input[i] == '\'') {
      result->append(input, span, i - span);
      result->append("'\\'");
      span = i;
    }
  }
  result->append(input, span, std::string::npos);
  result->push_back('\'');
}

std::string EncodeJSONString(const std::string& in) {
  static const char* hex = "0123456789abcdef";
  std::string out;
  out.reserve(in.size() + in.size() / 4);
  for (char c : in) {
    switch (c) {
      case '\b': out += "\\b"; break;
      case '\f': out += "\\f"; break;
      case '\n': out += "\\n"; break;
      case '\r': out += "\\r"; break;
      case '\t': out += "\\t"; break;
      case '\\': out += "\\\\"; break;
      case '"': out += "\\\""; break;
      default:
        if (c >= 0 && c < 0x20) {
          out += "\\u00";
          out += hex[(c >> 4) & 0xf];
          out += hex[c & 0xf];
        } else {
          out += c;
        }
    }
  }
  return out;
}

void PrintJSONString(const std::string& in) {
  std::string s = EncodeJSONString(in);
  fwrite(s.data(), 1, s.size(), stdout);
}

int EditDistance(const std::string& s1, const std::string& s2,
                 bool allow_replacements, int max_edit_distance) {
  int m = (int)s1.size();
  int n = (int)s2.size();
  std::vector<int> row(n + 1);
  for (int i = 1; i <= n; ++i)
    row[i] = i;
  for (int y = 1; y <= m; ++y) {
    row[0] = y;
    int best = row[0];
    int prev = y - 1;
    for (int x = 1; x <= n; ++x) {
      int old = row[x];
      if (allow_replacements) {
        row[x] = std::min(prev + (s1[y - 1] == s2[x - 1] ? 0 : 1),
                          std::min(row[x - 1], row[x]) + 1);
      } else {
        if (s1[y - 1] == s2[x - 1])
          row[x] = prev;
        else
          row[x] = std::min(row[x - 1], row[x]) + 1;
      }
      prev = old;
      best = std::min(best, row[x]);
    }
    if (max_edit_distance && best > max_edit_distance)
      return max_edit_distance + 1;
  }
  return row[n];
}

const char* SpellcheckStringV(const std::string& text,
                              const std::vector<const char*>& words) {
  const int kMax = 3;
  int min_distance = kMax + 1;
  const char* result = nullptr;
  for (const char* w : words) {
    int d = EditDistance(w, text, true, kMax);
    if (d < min_distance) {
      min_distance = d;
      result = w;
    }
  }
  return result;
}

const char* SpellcheckString(const char* text, ...) {
  va_list ap;
  va_start(ap, text);
  std::vector<const char*> words;
  const char* word;
  while ((word = va_arg(ap, const char*)))
    words.push_back(word);
  va_end(ap);
  return SpellcheckStringV(text, words);
}

static bool IsLatinAlpha(int c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

std::string StripAnsiEscapeCodes(const std::string& in) {
  std::string out;
  out.reserve(in.size());
  for (size_t i = 0; i < in.size(); ++i) {
    if (in[i] != '\33') {
      out.push_back(in[i]);
      continue;
    }
    if (i + 1 >= in.size())
      break;
    if (in[i + 1] != '[')
      continue;
    i += 2;
    while (i < in.size() && !IsLatinAlpha((unsigned char)in[i]))
      ++i;
  }
  return out;
}

void ElideMiddleInPlace(std::string& str, size_t width) {
  if (str.size() <= width)
    return;
  const size_t kEllipsis = 3;
  if (str.find('\x1b') == std::string::npos) {
    if (width <= kEllipsis) {
      str.assign("...", width);
      return;
    }
    size_t remaining = width - kEllipsis;
    size_t left = remaining / 2;
    size_t right = remaining - left;
    size_t gap_end = str.size() - right;
    str.replace(left, gap_end - left, "...");
    return;
  }

  // Slow path: keep ANSI escape sequences intact, count only visible chars.
  // First, split into visible characters and escape sequences.
  struct Piece {
    bool visible;
    size_t begin, len;
  };
  std::vector<Piece> pieces;
  size_t visible = 0;
  for (size_t i = 0; i < str.size();) {
    if (str[i] == '\x1b' && i + 1 < str.size() && str[i + 1] == '[') {
      size_t j = i + 2;
      while (j < str.size() && !IsLatinAlpha((unsigned char)str[j]))
