    if (cgroup_count >= 0 && cgroup_count < cpus)
      return cgroup_count;
    return cpus;
  }
  long n = sysconf(_SC_NPROCESSORS_ONLN);
  if (cgroup_count >= 0 && cgroup_count < n)
    return cgroup_count;
  return (int)n;
}

double GetLoadAverage() {
  double loadavg[3] = {0.0, 0.0, 0.0};
  if (getloadavg(loadavg, 3) < 0)
    return -0.0f;
  return loadavg[0];
}

int ReadFile(const std::string& path, std::string* contents, std::string* err) {
  int fd = open(path.c_str(), O_RDONLY | O_CLOEXEC);
  if (fd < 0) {
    *err = strerror(errno);
    return -errno;
  }
  struct stat st;
  if (fstat(fd, &st) < 0) {
    *err = strerror(errno);
    int e = errno;
    close(fd);
    return -e;
  }
  contents->clear();
  if (st.st_size > 0)
    contents->reserve(st.st_size + 1);
  char buf[64 << 10];
  ssize_t len;
  while ((len = read(fd, buf, sizeof(buf))) > 0)
    contents->append(buf, len);
  if (len < 0) {
    *err = strerror(errno);
    int e = errno;
    close(fd);
    contents->clear();
    return -e;
  }
  close(fd);
  return 0;
}

void SetCloseOnExec(int fd) {
  int flags = fcntl(fd, F_GETFD);
  if (flags < 0) {
    perror("fcntl(F_GETFD)");
  } else {
    if (fcntl(fd, F_SETFD, flags | FD_CLOEXEC) < 0)
      perror("fcntl(F_SETFD)");
  }
}

bool Truncate(const std::string& path, size_t size, std::string* err) {
  if (truncate(path.c_str(), size) < 0) {
    *err = strerror(errno);
    return false;
  }
  return true;
}

bool EndsWith(const std::string& str, const std::string& suffix) {
  return str.size() >= suffix.size() &&
         str.compare(str.size() - suffix.size(), suffix.size(), suffix) == 0;
}

std::string GetWorkingDirectory() {
  std::string ret;
  char* success = nullptr;
  do {
    ret.resize(ret.size() + 1024);
    errno = 0;
    success = getcwd(&ret[0], ret.size());
  } while (!success && errno == ERANGE);
  if (!success)
    Fatal("cannot determine working directory: %s", strerror(errno));
  ret.resize(strlen(ret.c_str()));
  return ret;
}

int64_t GetTimeMicros() {
  using namespace std::chrono;
  return duration_cast<microseconds>(steady_clock::now().time_since_epoch())
      .count();
}

int64_t GetTimeMillis() { return GetTimeMicros() / 1000; }
