// 64-bit string hash used for command fingerprints in the build log
// (rapidhash algorithm), and a 32-bit hash for in-memory tables.
#ifndef NJ_HASH_H_
#define NJ_HASH_H_

#include <stddef.h>
#include <stdint.h>
#include <string.h>

namespace hashing {

static const uint64_t kSecret[3] = {0x2d358dccaa6c78a5ull,
                                    0x8bb84b93962eacc9ull,
                                    0x4b33a62ed433d4a3ull};

inline void Mum(uint64_t* a, uint64_t* b) {
  __uint128_t r = *a;
  r *= *b;
  *a = (uint64_t)r;
  *b = (uint64_t)(r >> 64);
}

inline uint64_t Mix(uint64_t a, uint64_t b) {
  Mum(&a, &b);
  return a ^ b;
}

inline uint64_t Read64(const uint8_t* p) {
  uint64_t v;
  memcpy(&v, p, 8);
  return v;
}

inline uint64_t Read32(const uint8_t* p) {
  uint32_t v;
  memcpy(&v, p, 4);
  return v;
}

inline uint64_t ReadSmall(const uint8_t* p, size_t k) {
  return (((uint64_t)p[0]) << 56) | (((uint64_t)p[k >> 1]) << 32) | p[k - 1];
}

inline uint64_t Rapid(const void* key, size_t len,
                      uint64_t seed = 0xbdd89aa982704029ull) {
  const uint8_t* p = (const uint8_t*)key;
  seed ^= Mix(seed ^ kSecret[0], kSecret[1]) ^ len;
  uint64_t a, b;
  if (len <= 16) {
    if (len >= 4) {
      const uint8_t* plast = p + len - 4;
      a = (Read32(p) << 32) | Read32(plast);
      const uint64_t delta = ((len & 24) >> (len >> 3));
      b = ((Read32(p + delta) << 32) | Read32(plast - delta));
    } else if (len > 0) {
      a = ReadSmall(p, len);
      b = 0;
    } else {
      a = b = 0;
    }
  } else {
    size_t i = len;
    if (i > 48) {
      uint64_t see1 = seed, see2 = seed;
      while (i >= 48) {
        seed = Mix(Read64(p) ^ kSecret[0], Read64(p + 8) ^ seed);
        see1 = Mix(Read64(p + 16) ^ kSecret[1], Read64(p + 24) ^ see1);
        see2 = Mix(Read64(p + 32) ^ kSecret[2], Read64(p + 40) ^ see2);
        p += 48;
        i -= 48;
      }
      seed ^= see1 ^ see2;
    }
    if (i > 16) {
      seed = Mix(Read64(p) ^ kSecret[2], Read64(p + 8) ^ seed ^ kSecret[1]);
      if (i > 32)
        seed = Mix(Read64(p + 16) ^ kSecret[2], Read64(p + 24) ^ seed);
    }
    a = Read64(p + i - 16);
    b = Read64(p + i - 8);
  }
  a ^= kSecret[1];
  b ^= seed;
  Mum(&a, &b);
  return Mix(a ^ kSecret[0] ^ len, b ^ kSecret[1]);
}

}  // namespace hashing

#endif  // NJ_HASH_H_
