#include "metrics.h"

#include <stdio.h>

#include <algorithm>

#include "util.h"

Metrics* g_metrics = nullptr;

ScopedMetric::ScopedMetric(Metric* metric) : metric_(metric), start_(0) {
  if (!metric_)
    return;
  start_ = GetTimeMicros();
}

ScopedMetric::~ScopedMetric() {
  if (!metric_)
    return;
  metric_->count++;
  metric_->sum_us += GetTimeMicros() - start_;
}

