         "total (ms)");
  for (Metric* m : metrics_) {
    double total = m->sum_us / 1000.0;
    double avg = m->sum_us / (double)m->count;
    printf("%-*s\t%-6d\t%-8.1f\t%.1f\n", width, m->name.c_str(), m->count, avg,
           total);
  }
}
