// Variable scopes, unevaluated strings and rules.
#ifndef NJ_EVAL_ENV_H_
#define NJ_EVAL_ENV_H_

#include <map>
#include <memory>
#include <string>
#include <utility>
#include <vector>

struct Env {
  virtual ~Env() {}
  virtual std::string LookupVariable(const std::string& var) = 0;
};

/// A string with embedded variable references, kept unevaluated.
struct EvalString {
  std::string Evaluate(Env* env) const;
  /// Reconstruct a human readable form ("${var}" for references).
  std::string Unparse() const;

  void Clear() { parsed_.clear(); }
  bool empty() const { return parsed_.empty(); }

  void AddText(const char* text, size_t len);
  void AddSpecial(const char* text, size_t len);

 private:
  enum TokenType { RAW, SPECIAL };
  std::vector<std::pair<std::string, TokenType> > parsed_;
};

struct Rule {
  explicit Rule(const std::string& name) : name_(name) {}
  const std::string& name() const { return name_; }
  void AddBinding(const std::string& key, const EvalString& val);
  static bool IsReservedBinding(const std::string& var);
  const EvalString* GetBinding(const std::string& key) const;
  bool HasNonEmptyBinding(const std::string& key) const;

 private:
  std::string name_;
  std::map<std::string, EvalString> bindings_;
};

/// A scope of variables, possibly with a parent scope.
struct BindingEnv : public Env {
  BindingEnv() : parent_(nullptr) {}
  explicit BindingEnv(BindingEnv* parent) : parent_(parent) {}
  ~BindingEnv() override {}

  std::string LookupVariable(const std::string& var) override;

  void AddRule(std::unique_ptr<const Rule> rule);
  const Rule* LookupRule(const std::string& rule_name);
  const Rule* LookupRuleCurrentScope(const std::string& rule_name);
  const std::map<std::string, std::unique_ptr<const Rule> >& GetRules() const {
    return rules_;
  }

  void AddBinding(const std::string& key, const std::string& val);

  /// Lookup |var| in this scope; if absent evaluate |eval| in |env|; failing
  /// that, consult the parent scope.
  std::string LookupWithFallback(const std::string& var, const EvalString* eval,
                                 Env* env);

 private:
  std::map<std::string, std::string> bindings_;
  std::map<std::string, std::unique_ptr<const Rule> > rules_;
  BindingEnv* parent_;
};

#endif  // NJ_EVAL_ENV_H_
EOF
cat > eval_env.cc <<'EOF'
#include "eval_env.h"

std::string EvalString::Evaluate(Env* env) const {
  std::string result;
  for (const auto& tok : parsed_) {
    if (tok.second == RAW)
      result.append(tok.first);
    else
      result.append(env->LookupVariable(tok.first));
  }
  return result;
}

void EvalString::AddText(const char* text, size_t len) {
  if (!parsed_.empty() && parsed_.back().second == RAW) {
    parsed_.back().first.append(text, len);
  } else {
    parsed_.push_back(std::make_pair(std::string(text, len), RAW));
  }
}

void EvalString::AddSpecial(const char* text, size_t len) {
  parsed_.push_back(std::make_pair(std::string(text, len), SPECIAL));
}

std::string EvalString::Unparse() const {
  std::string result;
  for (const auto& tok : parsed_) {
    bool special = tok.second == SPECIAL;
    if (special)
      result.append("${");
    result.append(tok.first);
    if (special)
      result.append("}");
  }
  return result;
}

void Rule::AddBinding(const std::string& key, const EvalString& val) {
  bindings_[key] = val;
}

bool Rule::IsReservedBinding(const std::string& var) {
  return var == "command" || var == "depfile" || var == "dyndep" ||
         var == "description" || var == "deps" || var == "generator" ||
         var == "pool" || var == "restat" || var == "rspfile" ||
         var == "rspfile_content" || var == "msvc_deps_prefix";
}

const EvalString* Rule::GetBinding(const std::string& key) const {
  auto i = bindings_.find(key);
  if (i == bindings_.end())
    return nullptr;
  return &i->second;
}

bool Rule::HasNonEmptyBinding(const std::string& key) const {
  auto i = bindings_.find(key);
  return i != bindings_.end() && !i->second.empty();
}

std::string BindingEnv::LookupVariable(const std::string& var) {
  auto i = bindings_.find(var);
  if (i != bindings_.end())
    return i->second;
  if (parent_)
    return parent_->LookupVariable(var);
  return "";
}

void BindingEnv::AddBinding(const std::string& key, const std::string& val) {
  bindings_[key] = val;
}

void BindingEnv::AddRule(std::unique_ptr<const Rule> rule) {
  std::string name = rule->name();
  rules_[name] = std::move(rule);
}

const Rule* BindingEnv::LookupRuleCurrentScope(const std::string& rule_name) {
  auto i = rules_.find(rule_name);
  if (i == rules_.end())
    return nullptr;
  return i->second.get();
}

const Rule* BindingEnv::LookupRule(const std::string& rule_name) {
  auto i = rules_.find(rule_name);
  if (i != rules_.end())
    return i->second.get();
  if (parent_)
    return parent_->LookupRule(rule_name);
  return nullptr;
}

std::string BindingEnv::LookupWithFallback(const std::string& var,
                                           const EvalString* eval, Env* env) {
  auto i = bindings_.find(var);
  if (i != bindings_.end())
    return i->second;
  if (eval)
    return eval->Evaluate(env);
  if (parent_)
    return parent_->LookupVariable(var);
  return "";
}
EOF"}

