#include "lexer.h"

#include <stdio.h>
#include <string.h>

static inline bool IsVarChar(unsigned char c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
         (c >= '0' && c <= '9') || c == '_' || c == '-' || c == '.';
}

static inline bool IsSimpleVarChar(unsigned char c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
         (c >= '0' && c <= '9') || c == '_' || c == '-';
}

bool Lexer::Error(const std::string& message, std::string* err) {
  int line = 1;
  const char* line_start = input_;
  for (const char* p = input_; p < last_token_; ++p) {
    if (*p == '\n') {
      ++line;
      line_start = p + 1;
    }
  }
  int col = last_token_ ? (int)(last_token_ - line_start) : 0;

  char buf[1024];
  snprintf(buf, sizeof(buf), "%s:%d: ", filename_.c_str(), line);
  *err = buf;
  *err += message + "\n";

  const int kTruncateColumn = 72;
  if (col > 0 && col < kTruncateColumn) {
    int len;
    bool truncated = true;
    for (len = 0; len < kTruncateColumn; ++len) {
      if (line_start[len] == 0 || line_start[len] == '\n') {
        truncated = false;
        break;
      }
    }
    *err += std::string(line_start, len);
    if (truncated)
      *err += "...";
    *err += "\n";
    *err += std::string(col, ' ');
    *err += "^ near here";
  }
  return false;
}

