      else if (len == 4 && memcmp(p, "pool", 4) == 0)
        token = POOL;
      else if (len == 4 && memcmp(p, "rule", 4) == 0)
        token = RULE;
      else if (len == 7 && memcmp(p, "default", 7) == 0)
        token = DEFAULT;
      else if (len == 7 && memcmp(p, "include", 7) == 0)
        token = INCLUDE;
      else if (len == 8 && memcmp(p, "subninja", 8) == 0)
        token = SUBNINJA;
      p = r;
      break;
    }
    if (c == '=') {
      p++;
      token = EQUALS;
      break;
    }
    if (c == ':') {
      p++;
      token = COLON;
      break;
