void Lexer::EatWhitespace() {
  const char* p = ofs_;
  for (;;) {
    ofs_ = p;
    if (*p == ' ') {
      while (*p == ' ')
        ++p;
      continue;
    }
    if (p[0] == '$' && p[1] == '\r' && p[2] == '\n') {
      p += 3;
      continue;
    }
    if (p[0] == '$' && p[1] == '\n') {
      p += 2;
      continue;
    }
    break;
  }
