  if (!IsVarChar((unsigned char)*p)) {
    last_token_ = start;
    return false;
  }
  while (IsVarChar((unsigned char)*p))
    ++p;
  out->assign(start, p - start);
  last_token_ = start;
  ofs_ = p;
  EatWhitespace();
  return true;
}

bool Lexer::ReadEvalString(EvalString* eval, bool path, std::string* err) {
  const char* p = ofs_;
  const char* start;
  for (;;) {
    start = p;
    unsigned char c = (unsigned char)*p;
    if (c != '$' && c != ' ' && c != ':' && c != '\r' && c != '\n' &&
        c != '|' && c != '\0') {
      const char* r = p;
      for (;;) {
        unsigned char d = (unsigned char)*r;
        if (d == '$' || d == ' ' || d == ':' || d == '\r' || d == '\n' ||
            d == '|' || d == '\0')
          break;
        ++r;
      }
      eval->AddText(start, r - start);
      p = r;
      continue;
    }
    if (c == '\r' && p[1] == '\n') {
      if (path)
        p = start;
      else
        p += 2;
      break;
    }
    if (c == ' ' || c == ':' || c == '|' || c == '\n') {
      if (path) {
        p = start;
        break;
      }
      p++;
      if (c == '\n')
        break;
      eval->AddText(start, 1);
      continue;
    }
    if (c == '$') {
      unsigned char d = (unsigned char)p[1];
      if (d == '$') {
        eval->AddText("$", 1);
        p += 2;
        continue;
      }
      if (d == ' ') {
        eval->AddText(" ", 1);
        p += 2;
        continue;
      }
      if (d == '\r' && p[2] == '\n') {
        p += 3;
        while (*p == ' ')
          ++p;
        continue;
      }
      if (d == '\n') {
        p += 2;
        while (*p == ' ')
          ++p;
        continue;
      }
      if (d == '{') {
        const char* r = p + 2;
        while (IsVarChar((unsigned char)*r))
          ++r;
        if (r > p + 2 && *r == '}') {
          eval->AddSpecial(p + 2, r - (p + 2));
          p = r + 1;
          continue;
        }
        // Falls through to the bad escape below.
      }
      if (IsSimpleVarChar(d)) {
        const char* r = p + 1;
        while (IsSimpleVarChar((unsigned char)*r))
          ++r;
        eval->AddSpecial(p + 1, r - (p + 1));
        p = r;
        continue;
      }
      if (d == ':') {
        eval->AddText(":", 1);
        p += 2;
        continue;
      }
      if (d == '^') {
        if (!allow_dollar_caret_) {
          return Error(
              "using $^ escape requires specifying 'ninja_required_version' "
              "with version greater or equal 1.14",
              err);
        }
        eval->AddText("\n", 1);
        p += 2;
        continue;
      }
      if (d != '\n') {
        last_token_ = start;
        return Error("bad $-escape (literal $ must be written as $$)", err);
      }
    }
    if (c == '\0') {
      last_token_ = start;
      return Error("unexpected EOF", err);
    }
    // Anything else (e.g. a lone '\r').
    last_token_ = start;
    return Error(DescribeLastError(), err);
  }
  last_token_ = start;
  ofs_ = p;
  if (path)
    EatWhitespace();
  return true;
}
