cat > disk_interface.cc <<'EOF'
#include "disk_interface.h"

#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include "metrics.h"
#include "util.h"

static std::string DirName(const std::string& path) {
  std::string::size_type slash_pos = path.rfind('/');
  if (slash_pos == std::string::npos)
    return std::string();
  while (slash_pos > 0 && path[slash_pos - 1] == '/')
    --slash_pos;
  return path.substr(0, slash_pos);
}

bool DiskInterface::MakeDirs(const std::string& path) {
  std::string dir = DirName(path);
  if (dir.empty())
    return true;
  std::string err;
  TimeStamp mtime = Stat(dir, &err);
  if (mtime < 0) {
    Error("%s", err.c_str());
    return false;
  }
  if (mtime > 0)
    return true;
  if (!MakeDirs(dir))
    return false;
  return MakeDir(dir);
}

TimeStamp RealDiskInterface::Stat(const std::string& path,
                                  std::string* err) const {
  METRIC_RECORD("node stat");
  struct stat st;
  if (stat(path.c_str(), &st) < 0) {
    if (errno == ENOENT || errno == ENOTDIR)
      return 0;
    *err = "stat(" + path + "): " + strerror(errno);
    return -1;
  }
  if (st.st_mtime == 0)
    return 1;
  return (int64_t)st.st_mtim.tv_sec * 1000000000LL + st.st_mtim.tv_nsec;
}

bool RealDiskInterface::WriteFile(const std::string& path,
                                  const std::string& contents) {
  FILE* fp = fopen(path.c_str(), "w");
  if (fp == nullptr) {
    Error("WriteFile(%s): Unable to create file. %s", path.c_str(),
          strerror(errno));
    return false;
  }
  if (fwrite(contents.data(), 1, contents.length(), fp) < contents.length()) {
    Error("WriteFile(%s): Unable to write to the file. %s", path.c_str(),
          strerror(errno));
    fclose(fp);
    return false;
  }
  if (fclose(fp) == EOF) {
    Error("WriteFile(%s): Unable to close the file. %s", path.c_str(),
          strerror(errno));
    return false;
  }
  return true;
}

bool RealDiskInterface::MakeDir(const std::string& path) {
  if (mkdir(path.c_str(), 0777) < 0) {
    if (errno == EEXIST)
      return true;
    Error("mkdir(%s): %s", path.c_str(), strerror(errno));
    return false;
  }
  return true;
}

FileReader::Status RealDiskInterface::ReadFile(const std::string& path,
                                               std::string* contents,
                                               std::string* err) {
  switch (::ReadFile(path, contents, err)) {
    case 0:
      return Okay;
    case -ENOENT:
      return NotFound;
    default:
      return OtherError;
  }
}

int RealDiskInterface::RemoveFile(const std::string& path) {
  if (remove(path.c_str()) < 0) {
    switch (errno) {
      case ENOENT:
        return 1;
      default:
        Error("remove(%s): %s", path.c_str(), strerror(errno));
        return -1;
    }
  }
  return 0;
}
EOF"}

