// The build graph: files (Node), commands (Edge), pools and the overall State.
#ifndef NJ_GRAPH_H_
#define NJ_GRAPH_H_

#include <stdint.h>

#include <map>
#include <memory>
#include <queue>
#include <set>
#include <string>
#include <string_view>
#include <unordered_map>
#include <unordered_set>
#include <vector>

#include "disk_interface.h"
#include "eval_env.h"
#include "explanations.h"

struct Edge;
struct Pool;
struct State;
struct BuildLog;
struct DepsLog;
struct DyndepFile;

/// A file in the build graph.
struct Node {
  Node(const std::string& path, uint64_t slash_bits)
      : path_(path), slash_bits_(slash_bits) {}

  bool Stat(DiskInterface* disk_interface, std::string* err);
  void UpdatePhonyMtime(TimeStamp mtime) {
    if (!exists()) {
      if (mtime > mtime_)
        mtime_ = mtime;
    }
  }
  bool StatIfNecessary(DiskInterface* disk_interface, std::string* err) {
    if (status_known())
      return true;
    return Stat(disk_interface, err);
  }
  void ResetState() {
    mtime_ = -1;
    exists_ = ExistenceStatusUnknown;
    dirty_ = false;
  }
  void MarkMissing() {
    if (mtime_ == -1)
      mtime_ = 0;
    exists_ = ExistenceStatusMissing;
  }
  bool exists() const { return exists_ == ExistenceStatusExists; }
  bool status_known() const { return exists_ != ExistenceStatusUnknown; }

  const std::string& path() const { return path_; }
  std::string PathDecanonicalized() const { return path_; }
  uint64_t slash_bits() const { return slash_bits_; }
  TimeStamp mtime() const { return mtime_; }

  bool dirty() const { return dirty_; }
  void set_dirty(bool dirty) { dirty_ = dirty; }
  void MarkDirty() { dirty_ = true; }

  bool dyndep_pending() const { return dyndep_pending_; }
  void set_dyndep_pending(bool pending) { dyndep_pending_ = pending; }

  Edge* in_edge() const { return in_edge_; }
  void set_in_edge(Edge* edge) { in_edge_ = edge; }

  bool generated_by_dep_loader() const { return generated_by_dep_loader_; }
  void set_generated_by_dep_loader(bool value) {
    generated_by_dep_loader_ = value;
  }

  int id() const { return id_; }
  void set_id(int id) { id_ = id; }

  /// Creation order within the State; used for deterministic ordering.
  size_t seq() const { return seq_; }

  const std::vector<Edge*>& out_edges() const { return out_edges_; }
  const std::vector<Edge*>& validation_out_edges() const {
    return validation_out_edges_;
  }
  void AddOutEdge(Edge* edge) { out_edges_.push_back(edge); }
  void AddValidationOutEdge(Edge* edge) {
    validation_out_edges_.push_back(edge);
  }

  void Dump(const char* prefix = "") const;

 private:
  friend struct State;
  enum ExistenceStatus {
    ExistenceStatusUnknown,
    ExistenceStatusMissing,
    ExistenceStatusExists
  };

  std::string path_;
  uint64_t slash_bits_ = 0;
  TimeStamp mtime_ = -1;
  ExistenceStatus exists_ = ExistenceStatusUnknown;
  bool dirty_ = false;
  bool dyndep_pending_ = false;
  bool generated_by_dep_loader_ = true;
  Edge* in_edge_ = nullptr;
  std::vector<Edge*> out_edges_;
  std::vector<Edge*> validation_out_edges_;
  int id_ = -1;
  size_t seq_ = 0;
};

/// A command connecting inputs to outputs.
struct Edge {
  enum VisitMark { VisitNone, VisitInStack, VisitDone };

  bool AllInputsReady() const;

  /// Expand the command, optionally appending the rspfile content.
  std::string EvaluateCommand(bool incl_rsp_file = false) const;

  std::string GetBinding(const std::string& key) const;
  bool GetBindingBool(const std::string& key) const;
  std::string GetUnescapedDepfile() const;
  std::string GetUnescapedDyndep() const;
  std::string GetUnescapedRspfile() const;

  void Dump(const char* prefix = "") const;

  const Rule* rule_ = nullptr;
  Pool* pool_ = nullptr;
  std::vector<Node*> inputs_;
  std::vector<Node*> outputs_;
  std::vector<Node*> validations_;
  Node* dyndep_ = nullptr;
  BindingEnv* env_ = nullptr;
  VisitMark mark_ = VisitNone;
  size_t id_ = 0;
  int64_t critical_path_weight_ = -1;
  bool outputs_ready_ = false;
  bool deps_loaded_ = false;
  bool deps_missing_ = false;
  bool generated_by_dep_loader_ = false;
  TimeStamp command_start_time_ = 0;
  /// Jobserver token held while running (-1 none, 0 implicit, >0 explicit).
  int job_slot_ = -1;

  const Rule& rule() const { return *rule_; }
  Pool* pool() const { return pool_; }
  int weight() const { return 1; }
  bool outputs_ready() const { return outputs_ready_; }

  int64_t critical_path_weight() const { return critical_path_weight_; }
  void set_critical_path_weight(int64_t w) { critical_path_weight_ = w; }

  int implicit_deps_ = 0;
  int order_only_deps_ = 0;
  bool is_implicit(size_t index) const {
    return index >= inputs_.size() - order_only_deps_ - implicit_deps_ &&
           !is_order_only(index);
  }
  bool is_order_only(size_t index) const {
    return index >= inputs_.size() - order_only_deps_;
  }

  int implicit_outs_ = 0;
  bool is_implicit_out(size_t index) const {
    return index >= outputs_.size() - implicit_outs_;
  }

  bool is_phony() const;
  bool use_console() const;
  bool maybe_phonycycle_diagnostic() const;
};

struct EdgeIdLess {
  bool operator()(const Edge* a, const Edge* b) const {
    return a->id_ < b->id_;
  }
};

struct NodeSeqLess {
  bool operator()(const Node* a, const Node* b) const {
    return a->seq() < b->seq();
  }
};

typedef std::set<Edge*, EdgeIdLess> EdgeSet;

/// Ready-queue ordering: higher critical path weight first, then lower id.
struct EdgePriorityLess {
  bool operator()(const Edge* e1, const Edge* e2) const {
    const int64_t cw1 = e1->critical_path_weight();
    const int64_t cw2 = e2->critical_path_weight();
    if (cw1 != cw2)
      return cw1 < cw2;
    return e1->id_ > e2->id_;
  }
};

struct EdgePriorityGreater {
  bool operator()(const Edge* e1, const Edge* e2) const {
    return EdgePriorityLess()(e2, e1);
  }
};

class EdgePriorityQueue
    : public std::priority_queue<Edge*, std::vector<Edge*>, EdgePriorityLess> {
 public:
  void clear() { c.clear(); }
};

/// A pool limits the number of concurrently running edges.
struct Pool {
  Pool(const std::string& name, int depth)
      : name_(name), current_use_(0), depth_(depth) {}

  bool is_valid() const { return depth_ >= 0; }
  int depth() const { return depth_; }
  const std::string& name() const { return name_; }
  int current_use() const { return current_use_; }

  bool ShouldDelayEdge() const { return depth_ != 0; }
  void EdgeScheduled(const Edge& edge);
  void EdgeFinished(const Edge& edge);
  void DelayEdge(Edge* edge);
  void RetrieveReadyEdges(EdgePriorityQueue* ready_queue);
  void Dump() const;

 private:
  std::string name_;
  int current_use_;
  int depth_;
  std::set<Edge*, EdgePriorityGreater> delayed_;
};

/// Bucket-count model of the node table (for "-d stats").
size_t PathTableBucketCount(size_t entries);

struct State {
  static Pool kDefaultPool;
  static Pool kConsolePool;

  State();
  ~State();

  void AddPool(Pool* pool);
  Pool* LookupPool(const std::string& pool_name);

  Edge* AddEdge(const Rule* rule);

  Node* GetNode(std::string_view path, uint64_t slash_bits);
  Node* LookupNode(std::string_view path) const;
  Node* SpellcheckNode(const std::string& path);

  void AddIn(Edge* edge, std::string_view path, uint64_t slash_bits);
  bool AddOut(Edge* edge, std::string_view path, uint64_t slash_bits,
              std::string* err);
  void AddValidation(Edge* edge, std::string_view path, uint64_t slash_bits);
  bool AddDefault(std::string_view path, std::string* error);

  void Reset();
  void Dump();

  std::vector<Node*> RootNodes(std::string* error) const;
  std::vector<Node*> DefaultNodes(std::string* error) const;

  const Rule* phony_rule() const { return phony_rule_; }

  /// All nodes, in creation order.
  std::vector<Node*> nodes_;
  std::unordered_map<std::string_view, Node*> paths_;
  std::map<std::string, Pool*> pools_;
  std::vector<Edge*> edges_;
  BindingEnv bindings_;
  std::vector<Node*> defaults_;

 private:
  const Rule* phony_rule_ = nullptr;
};

struct DepfileParserOptions {};

/// Loads implicit dependencies (from depfiles or the deps log) for an edge.
struct ImplicitDepLoader {
  ImplicitDepLoader(State* state, DepsLog* deps_log,
                    DiskInterface* disk_interface,
                    DepfileParserOptions const* depfile_parser_options,
                    Explanations* explanations)
      : state_(state),
        disk_interface_(disk_interface),
        deps_log_(deps_log),
        depfile_parser_options_(depfile_parser_options),
        explanations_(explanations) {}
  virtual ~ImplicitDepLoader() {}

  bool LoadDeps(Edge* edge, std::string* err);
  DepsLog* deps_log() const { return deps_log_; }

 protected:
