  if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
      (c >= '0' && c <= '9'))
    return true;
  if (c >= 0x80)
    return true;
  switch (c) {
    case '+': case ',': case '/': case '_': case ':': case '.': case '~':
    case '(': case ')': case '}': case '{': case '%': case '=': case '@':
    case '[': case ']': case '!': case '-':
      return true;
    default:
      return false;
  }
}

bool DepfileParser::Parse(std::string* content, std::string* err) {
  // The buffer is NUL terminated (std::string guarantees content[size()]).
  char* in = &(*content)[0];
  char* end = in + content->size();
  bool have_target = false;
  bool parsing_targets = true;
  bool poisoned_input = false;
  bool is_empty = true;
  while (in < end) {
    bool have_newline = false;
    char* out = in;
    char* filename = out;
    for (;;) {
      char* start = in;
      unsigned char c = (unsigned char)*in;
      if (c == '\\') {
        // Count the run of backslashes.
        char* r = in;
        while (*r == '\\')
          ++r;
        size_t k = r - in;
        unsigned char next = (unsigned char)*r;
        if (next == ' ') {
          in = r + 1;
          int len = (int)(in - start);
          if (k % 2 == 1) {
            // 2N+1 backslashes plus space -> N backslashes plus space.
            int n = len / 2 - 1;
            if (out < start)
              memset(out, '\\', n);
            out += n;
            *out++ = ' ';
            continue;
          }
          // 2N backslashes plus space -> 2N backslashes, end of filename.
          if (out < start)
            memset(out, '\\', len - 1);
          out += len - 1;
          break;
        }
        if (next == '#') {
          in = r + 1;
          int len = (int)(in - start);
          if (len > 2 && out < start)
            memset(out, '\\', len - 2);
          out += len - 2;
          *out++ = '#';
          continue;
        }
        if (next == ':') {
          unsigned char after = (unsigned char)r[1];
          if (after == '\0' || after == ' ' || after == '\r' ||
              after == '\n' || after == '\t') {
            // Backslash(es) and colon followed by whitespace: plain text,
            // not an escaped colon.
            in = r + 2;
            int len = (int)(in - start - 1);
            if (out < start)
              memmove(out, start, len);
            out += len;
            if (*(in - 1) == '\n')
              have_newline = true;
            break;
          }
          in = r + 1;
          int len = (int)(in - start);
          if (len > 2 && out < start)
            memset(out, '\\', len - 2);
          out += len - 2;
          *out++ = ':';
          continue;
        }
        if (next != '\0' && next != '\r' && next != '\n') {
          // Backslashes followed by an ordinary character: plain text.
          in = r + 1;
          int len = (int)(in - start);
          if (out < start)
            memmove(out, start, len);
          out += len;
          continue;
        }
        // Backslash run followed by NUL, CR or LF.
        if (k == 1) {
          if (next == '\n') {
            in = r + 1;  // line continuation
            break;
          }
          if (next == '\r' && r[1] == '\n') {
            in = r + 2;
            break;
          }
          // A lone backslash: swallow it.
          in = start + 1;
          break;
        }
        // k >= 2: all backslashes form plain text (the last one acting as
        // the "any character").
        in = r;
        int len = (int)(in - start);
        if (out < start)
          memmove(out, start, len);
        out += len;
        continue;
      }
      if (c == '$' && in[1] == '$') {
        in += 2;
        *out++ = '$';
        continue;
      }
      if (IsPlainChar(c)) {
        char* r = in;
        while (IsPlainChar((unsigned char)*r))
          ++r;
        in = r;
        int len = (int)(in - start);
        if (out < start)
          memmove(out, start, len);
        out += len;
        continue;
      }
      if (c == '\0') {
        ++in;
        break;
      }
      if (c == '\n') {
        ++in;
        have_newline = true;
        break;
      }
      if (c == '\r' && in[1] == '\n') {
        in += 2;
        have_newline = true;
        break;
      }
      // Any other character (e.g. whitespace) ends the current filename.
      ++in;
      break;
    }

    int len = (int)(out - filename);
    const bool is_dependency = !parsing_targets;
    if (len > 0 && filename[len - 1] == ':') {
      len--;
      parsing_targets = false;
      have_target = true;
    }

    if (len > 0) {
      is_empty = false;
      std::string piece(filename, len);
      auto pos = std::find(ins_.begin(), ins_.end(), piece);
      if (pos == ins_.end()) {
        if (is_dependency) {
          if (poisoned_input) {
            *err = "inputs may not also have inputs";
            return false;
          }
          ins_.push_back(piece);
        } else {
          if (std::find(outs_.begin(), outs_.end(), piece) == outs_.end())
            outs_.push_back(piece);
        }
      } else if (!is_dependency) {
        poisoned_input = true;
      }
    }

    if (have_newline)
      parsing_targets = true;
  }
  if (!have_target && !is_empty) {
    *err = "expected ':' in depfile";
    return false;
  }
  return true;
}
