  Edge* edge = new Edge();
  edge->rule_ = rule;
  edge->pool_ = &State::kDefaultPool;
  edge->env_ = &bindings_;
  edge->id_ = edges_.size();
  edges_.push_back(edge);
  return edge;
}

Node* State::GetNode(std::string_view path, uint64_t slash_bits) {
  Node* node = LookupNode(path);
  if (node)
    return node;
  node = new Node(std::string(path), slash_bits);
  node->seq_ = nodes_.size();
  nodes_.push_back(node);
  paths_[std::string_view(node->path())] = node;
  return node;
}

Node* State::LookupNode(std::string_view path) const {
  auto i = paths_.find(path);
  if (i != paths_.end())
    return i->second;
  return nullptr;
}

Node* State::SpellcheckNode(const std::string& path) {
  const int kMaxValidEditDistance = 3;
  int min_distance = kMaxValidEditDistance + 1;
  Node* result = nullptr;
  for (Node* n : nodes_) {
    int distance = EditDistance(n->path(), path, true, kMaxValidEditDistance);
    if (distance < min_distance) {
      min_distance = distance;
      result = n;
    }
  }
  return result;
}

void State::AddIn(Edge* edge, std::string_view path, uint64_t slash_bits) {
  Node* node = GetNode(path, slash_bits);
  node->set_generated_by_dep_loader(false);
  edge->inputs_.push_back(node);
  node->AddOutEdge(edge);
}

bool State::AddOut(Edge* edge, std::string_view path, uint64_t slash_bits,
                   std::string* err) {
  Node* node = GetNode(path, slash_bits);
  if (Edge* other = node->in_edge()) {
    if (other == edge)
      *err = std::string(path) + " is defined as an output multiple times";
    else
      *err = "multiple rules generate " + std::string(path);
    return false;
  }
  edge->outputs_.push_back(node);
  node->set_in_edge(edge);
  node->set_generated_by_dep_loader(false);
  return true;
}

void State::AddValidation(Edge* edge, std::string_view path,
                          uint64_t slash_bits) {
  Node* node = GetNode(path, slash_bits);
  edge->validations_.push_back(node);
  node->AddValidationOutEdge(edge);
}

bool State::AddDefault(std::string_view path, std::string* err) {
  Node* node = LookupNode(path);
  if (!node) {
    *err = "unknown target '" + std::string(path) + "'";
    return false;
  }
  defaults_.push_back(node);
  return true;
}

std::vector<Node*> State::RootNodes(std::string* err) const {
  std::vector<Node*> root_nodes;
  for (Edge* e : edges_) {
    for (Node* out : e->outputs_) {
      if (out->out_edges().empty())
        root_nodes.push_back(out);
    }
  }
  if (!edges_.empty() && root_nodes.empty())
    *err = "could not determine root nodes of build graph";
  return root_nodes;
}

std::vector<Node*> State::DefaultNodes(std::string* err) const {
  return defaults_.empty() ? RootNodes(err) : defaults_;
}

void State::Reset() {
  for (Node* n : nodes_)
    n->ResetState();
  for (Edge* e : edges_) {
    e->outputs_ready_ = false;
    e->deps_loaded_ = false;
    e->mark_ = Edge::VisitNone;
  }
}

void State::Dump() {
  for (Node* node : nodes_) {
    printf("%s %s [id:%d]\n", node->path().c_str(),
           node->status_known() ? (node->dirty() ? "dirty" : "clean")
                                : "unknown",
           node->id());
  }
  if (!pools_.empty()) {
    printf("resource_pools:\n");
    for (auto& p : pools_) {
      if (!p.second->name().empty())
        p.second->Dump();
    }
  }
}
