// Dirty-state computation and dependency loading.
#include "graph.h"

#include <assert.h>
#include <inttypes.h>
#include <stdio.h>

#include <algorithm>
#include <deque>

#include "build_log.h"
#include "deps_log.h"
#include "depfile_parser.h"
#include "dyndep.h"
#include "metrics.h"
#include "util.h"

bool DependencyScan::RecomputeDirty(Node* initial_node,
                                    std::vector<Node*>* validation_nodes,
                                    std::string* err) {
  std::vector<Node*> stack;
  std::vector<Node*> new_validation_nodes;
  std::deque<Node*> nodes(1, initial_node);

  while (!nodes.empty()) {
    Node* node = nodes.front();
    nodes.pop_front();

    stack.clear();
    new_validation_nodes.clear();

    if (!RecomputeNodeDirty(node, &stack, &new_validation_nodes, err))
      return false;
    nodes.insert(nodes.end(), new_validation_nodes.begin(),
                 new_validation_nodes.end());
    if (!new_validation_nodes.empty()) {
      assert(validation_nodes);
      validation_nodes->insert(validation_nodes->end(),
                               new_validation_nodes.begin(),
                               new_validation_nodes.end());
    }
  }
  return true;
}

bool DependencyScan::RecomputeNodeDirty(Node* node, std::vector<Node*>* stack,
                                        std::vector<Node*>* validation_nodes,
                                        std::string* err) {
  Edge* edge = node->in_edge();
  if (!edge) {
    // Leaf node: dirty if missing.
    if (node->status_known())
      return true;
    if (!node->StatIfNecessary(disk_interface_, err))
      return false;
    if (!node->exists())
      explanations_.Record(node, "%s has no in-edge and is missing",
                           node->path().c_str());
    node->set_dirty(!node->exists());
    return true;
  }

  if (edge->mark_ == Edge::VisitDone)
    return true;

  if (!VerifyDAG(node, stack, err))
    return false;

  edge->mark_ = Edge::VisitInStack;
  stack->push_back(node);

  bool dirty = false;
  edge->outputs_ready_ = true;
  edge->deps_missing_ = false;

  if (!edge->deps_loaded_) {
    // First visit: a pending dyndep file that is ready gets loaded now.
    if (edge->dyndep_ && edge->dyndep_->dyndep_pending()) {
      if (!RecomputeNodeDirty(edge->dyndep_, stack, validation_nodes, err))
        return false;

      if (!edge->dyndep_->in_edge() ||
          edge->dyndep_->in_edge()->outputs_ready()) {
        if (!LoadDyndeps(edge->dyndep_, err))
          return false;
      }
    }
  }

  for (Node* o : edge->outputs_) {
    if (!o->StatIfNecessary(disk_interface_, err))
      return false;
  }

  if (!edge->deps_loaded_) {
    edge->deps_loaded_ = true;
    if (!dep_loader_.LoadDeps(edge, err)) {
      if (!err->empty())
        return false;
      // Missing dependency info: rebuild to regenerate it.
      dirty = edge->deps_missing_ = true;
    }
  }

  validation_nodes->insert(validation_nodes->end(), edge->validations_.begin(),
                           edge->validations_.end());

  Node* most_recent_input = nullptr;
  for (size_t idx = 0; idx < edge->inputs_.size(); ++idx) {
    Node* in = edge->inputs_[idx];
    if (!RecomputeNodeDirty(in, stack, validation_nodes, err))
      return false;

    if (Edge* in_edge = in->in_edge()) {
      if (!in_edge->outputs_ready_)
        edge->outputs_ready_ = false;
    }

    if (!edge->is_order_only(idx)) {
      if (in->dirty()) {
        explanations_.Record(node, "%s is dirty", in->path().c_str());
        dirty = true;
      } else {
        if (!most_recent_input || in->mtime() > most_recent_input->mtime())
          most_recent_input = in;
      }
    }
  }

  if (!dirty)
    if (!RecomputeOutputsDirty(edge, most_recent_input, &dirty, err))
      return false;

  for (Node* o : edge->outputs_) {
    if (dirty)
      o->MarkDirty();
  }

  if (dirty && !(edge->is_phony() && edge->inputs_.empty()))
    edge->outputs_ready_ = false;

  edge->mark_ = Edge::VisitDone;
  assert(stack->back() == node);
  stack->pop_back();
  return true;
}

bool DependencyScan::VerifyDAG(Node* node, std::vector<Node*>* stack,
                               std::string* err) {
  Edge* edge = node->in_edge();
  assert(edge != nullptr);

  if (edge->mark_ != Edge::VisitInStack)
    return true;

  auto start = stack->begin();
  while (start != stack->end() && (*start)->in_edge() != edge)
    ++start;
  assert(start != stack->end());

  // Report the cycle starting at |node| rather than another output of the
  // same edge.
  *start = node;

  *err = "dependency cycle: ";
  for (auto i = start; i != stack->end(); ++i) {
    *err += (*i)->path();
    *err += " -> ";
  }
  *err += (*start)->path();

  if ((start + 1) == stack->end() && edge->maybe_phonycycle_diagnostic()) {
    *err += " [-w phonycycle=err]";
  }
  return false;
}

bool DependencyScan::RecomputeOutputsDirty(Edge* edge, Node* most_recent_input,
                                           bool* outputs_dirty,
                                           std::string* err) {
  std::string command = edge->EvaluateCommand(/*incl_rsp_file=*/true);
  for (Node* o : edge->outputs_) {
    if (RecomputeOutputDirty(edge, most_recent_input, command, o)) {
      *outputs_dirty = true;
      return true;
    }
  }
  return true;
}

bool DependencyScan::RecomputeOutputDirty(const Edge* edge,
                                          const Node* most_recent_input,
                                          const std::string& command,
                                          Node* output) {
  if (edge->is_phony()) {
    // Phony edges have no outputs of their own; they're only dirty if they
    // have no inputs and the output is missing.
    if (edge->inputs_.empty() && !output->exists()) {
      explanations_.Record(
          output, "output %s of phony edge with no inputs doesn't exist",
          output->path().c_str());
      return true;
    }
    if (most_recent_input)
      output->UpdatePhonyMtime(most_recent_input->mtime());
    return false;
  }

  if (!output->exists()) {
    explanations_.Record(output, "output %s doesn't exist",
                         output->path().c_str());
    return true;
  }

  BuildLog::LogEntry* entry = nullptr;

  // For restat rules, compare the mtime recorded in the log, not the
  // actual output mtime.
  bool used_restat = false;
  if (edge->GetBindingBool("restat") && build_log() &&
      (entry = build_log()->LookupByOutput(output->path()))) {
    used_restat = true;
  }

  if (!used_restat && most_recent_input &&
      output->mtime() < most_recent_input->mtime()) {
    explanations_.Record(output,
                         "output %s older than most recent input %s "
                         "(%" PRId64 " vs %" PRId64 ")",
                         output->path().c_str(),
                         most_recent_input->path().c_str(), output->mtime(),
                         most_recent_input->mtime());
    return true;
  }

  if (build_log()) {
    bool generator = edge->GetBindingBool("generator");
    if (entry || (entry = build_log()->LookupByOutput(output->path()))) {
      if (!generator &&
          BuildLog::LogEntry::HashCommand(command) != entry->command_hash) {
        explanations_.Record(output, "command line changed for %s",
                             output->path().c_str());
        return true;
      }
      if (most_recent_input && entry->mtime < most_recent_input->mtime()) {
        explanations_.Record(
            output,
            "recorded mtime of %s older than most recent input %s "
            "(%" PRId64 " vs %" PRId64 ")",
            output->path().c_str(), most_recent_input->path().c_str(),
            entry->mtime, most_recent_input->mtime());
        return true;
      }
    }
    if (!entry && !generator) {
      explanations_.Record(output, "command line not found in log for %s",
                           output->path().c_str());
      return true;
    }
  }

  return false;
}

bool DependencyScan::LoadDyndeps(Node* node, std::string* err) const {
  return dyndep_loader_.LoadDyndeps(node, err);
}

bool DependencyScan::LoadDyndeps(Node* node, DyndepFile* ddf,
                                 std::string* err) const {
  return dyndep_loader_.LoadDyndeps(node, ddf, err);
}

bool ImplicitDepLoader::LoadDeps(Edge* edge, std::string* err) {
  std::string deps_type = edge->GetBinding("deps");
  if (!deps_type.empty())
    return LoadDepsFromLog(edge, err);

  std::string depfile = edge->GetUnescapedDepfile();
  if (!depfile.empty())
    return LoadDepFile(edge, depfile, err);

  return true;
}

bool ImplicitDepLoader::LoadDepFile(Edge* edge, const std::string& path,
                                    std::string* err) {
  METRIC_RECORD("depfile load");
  std::string content;
  switch (disk_interface_->ReadFile(path, &content, err)) {
    case DiskInterface::Okay:
      break;
    case DiskInterface::NotFound:
      err->clear();
      break;
    case DiskInterface::OtherError:
      *err = "loading '" + path + "': " + *err;
      return false;
  }
  Node* first_output = edge->outputs_[0];
  if (content.empty()) {
    explanations_.Record(first_output, "depfile '%s' is missing",
                         path.c_str());
    return false;
  }

  DepfileParser depfile;
  std::string depfile_err;
  if (!depfile.Parse(&content, &depfile_err)) {
    *err = path + ": " + depfile_err;
    return false;
  }

  if (depfile.outs_.empty()) {
    *err = path + ": no outputs declared";
    return false;
  }

  uint64_t unused;
  std::string primary_out = depfile.outs_[0];
  CanonicalizePath(&primary_out, &unused);

  if (first_output->path() != primary_out) {
    explanations_.Record(first_output,
                         "expected depfile '%s' to mention '%s', got '%s'",
                         path.c_str(), first_output->path().c_str(),
                         primary_out.c_str());
    return false;
  }

  // All mentioned outputs must be outputs of the edge.
  for (size_t i = 0; i < depfile.outs_.size(); ++i) {
    std::string o = depfile.outs_[i];
    if (i == 0)
      o = primary_out;
    bool found = false;
    for (Node* n : edge->outputs_) {
      if (n->path() == o) {
        found = true;
        break;
      }
    }
    if (!found) {
      *err = path + ": depfile mentions '" + o +
             "' as an output, but no such output was declared";
      return false;
    }
  }

  return ProcessDepfileDeps(edge, &depfile.ins_, err);
}

bool ImplicitDepLoader::ProcessDepfileDeps(
    Edge* edge, std::vector<std::string>* depfile_ins, std::string* err) {
  std::vector<Node*>::iterator implicit_dep =
      PreallocateSpace(edge, depfile_ins->size());

  for (std::string& in : *depfile_ins) {
    uint64_t slash_bits;
    CanonicalizePath(&in, &slash_bits);
    Node* node = state_->GetNode(in, slash_bits);
    *implicit_dep = node;
    ++implicit_dep;
    node->AddOutEdge(edge);
    CreatePhonyInEdge(node);
  }
  return true;
}

bool ImplicitDepLoader::LoadDepsFromLog(Edge* edge, std::string* err) {
  Node* output = edge->outputs_[0];
  DepsLog::Deps* deps = deps_log_ ? deps_log_->GetDeps(output) : nullptr;
  if (!deps) {
    explanations_.Record(output, "deps for '%s' are missing",
                         output->path().c_str());
    return false;
  }

  if (output->mtime() > deps->mtime) {
    explanations_.Record(output,
                         "stored deps info out of date for '%s' (%" PRId64
                         " vs %" PRId64 ")",
                         output->path().c_str(), deps->mtime, output->mtime());
    return false;
  }

  Node** nodes = deps->nodes;
  size_t node_count = deps->node_count;
  edge->inputs_.insert(edge->inputs_.end() - edge->order_only_deps_, nodes,
                       nodes + node_count);
  edge->implicit_deps_ += node_count;
  for (size_t i = 0; i < node_count; ++i) {
    nodes[i]->AddOutEdge(edge);
    CreatePhonyInEdge(nodes[i]);
  }
  return true;
}

std::vector<Node*>::iterator ImplicitDepLoader::PreallocateSpace(Edge* edge,
                                                                 int count) {
  edge->inputs_.insert(edge->inputs_.end() - edge->order_only_deps_,
                       (size_t)count, nullptr);
  edge->implicit_deps_ += count;
  return edge->inputs_.end() - edge->order_only_deps_ - count;
}

void ImplicitDepLoader::CreatePhonyInEdge(Node* node) {
  if (node->in_edge())
    return;

  Edge* phony_edge = state_->AddEdge(state_->phony_rule());
  phony_edge->generated_by_dep_loader_ = true;
  node->set_in_edge(phony_edge);
  phony_edge->outputs_.push_back(node);

  // The node may already have been stat'ed without an in-edge, so make the
  // new edge ready to avoid a stuck build.
  phony_edge->outputs_ready_ = true;
}

void InputsCollector::VisitNode(const Node* node) {
  const Edge* edge = node->in_edge();
  if (!edge)
    return;

  for (const Node* input : edge->inputs_) {
    if (!visited_nodes_.insert(input).second)
      continue;

    VisitNode(input);

    const Edge* input_edge = input->in_edge();
    if (!(input_edge && input_edge->is_phony()))
      inputs_.push_back(input);
  }
}

std::vector<std::string> InputsCollector::GetInputsAsStrings(
    bool shell_escape) const {
  std::vector<std::string> result;
  result.reserve(inputs_.size());
  for (const Node* input : inputs_) {
    std::string unescaped = input->PathDecanonicalized();
    if (shell_escape) {
      std::string path;
      GetShellEscapedString(unescaped, &path);
      result.push_back(std::move(path));
    } else {
      result.push_back(std::move(unescaped));
    }
  }
  return result;
}

void CommandCollector::CollectFrom(const Node* node) {
  assert(node);
  if (!visited_nodes_.insert(node).second)
    return;

  Edge* edge = node->in_edge();
  if (!edge || !visited_edges_.insert(edge).second)
    return;

  for (Node* input_node : edge->inputs_)
    CollectFrom(input_node);

  if (!edge->is_phony())
    in_edges.push_back(edge);
}
