#include "build_log.h"

#include <errno.h>
#include <inttypes.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "graph.h"
#include "hash.h"
#include "metrics.h"
#include "util.h"

static const char kFileSignature[] = "# ninja log v%d\n";
static const int kOldestSupportedVersion = 7;
static const int kCurrentVersion = 7;

uint64_t BuildLog::LogEntry::HashCommand(std::string_view command) {
  return hashing::Rapid(command.data(), command.size());
}

BuildLog::BuildLog() {}

BuildLog::~BuildLog() { Close(); }

BuildLog::LogEntry* BuildLog::Insert(const std::string& output) {
  LogEntry* e = new LogEntry(output);
  order_.push_back(e);
  index_[std::string_view(e->output)] = order_.size() - 1;
  return e;
}

void BuildLog::Erase(const std::string& output) {
  auto it = index_.find(std::string_view(output));
  if (it == index_.end())
    return;
  size_t idx = it->second;
  LogEntry* victim = order_[idx];
  index_.erase(it);
  if (idx != order_.size() - 1) {
    order_[idx] = order_.back();
    index_[std::string_view(order_[idx]->output)] = idx;
  }
  order_.pop_back();
  delete victim;
}

BuildLog::LogEntry* BuildLog::LookupByOutput(const std::string& path) {
  auto it = index_.find(std::string_view(path));
  if (it != index_.end())
    return order_[it->second];
  return nullptr;
}

bool BuildLog::OpenForWrite(const std::string& path, const BuildLogUser& user,
                            std::string* err) {
  if (needs_recompaction_) {
    if (!Recompact(path, user, err))
      return false;
  }
  log_file_path_ = path;
  return true;
}

bool BuildLog::RecordCommand(Edge* edge, int start_time, int end_time,
                             TimeStamp mtime) {
  std::string command = edge->EvaluateCommand(true);
  uint64_t command_hash = LogEntry::HashCommand(command);
  for (Node* out : edge->outputs_) {
    const std::string& path = out->path();
    LogEntry* log_entry = LookupByOutput(path);
    if (!log_entry)
      log_entry = Insert(path);
    log_entry->command_hash = command_hash;
    log_entry->start_time = start_time;
    log_entry->end_time = end_time;
    log_entry->mtime = mtime;

    if (!OpenForWriteIfNeeded())
      return false;
    if (log_file_) {
      if (!WriteEntry(log_file_, *log_entry))
        return false;
      if (fflush(log_file_) != 0)
        return false;
    }
  }
  return true;
}

void BuildLog::Close() {
  OpenForWriteIfNeeded();  // create the file even if nothing was recorded
  if (log_file_)
    fclose(log_file_);
  log_file_ = nullptr;
}

bool BuildLog::OpenForWriteIfNeeded() {
  if (log_file_ || log_file_path_.empty())
    return true;
  log_file_ = fopen(log_file_path_.c_str(), "ab");
  if (!log_file_)
    return false;
  if (setvbuf(log_file_, nullptr, _IOLBF, BUFSIZ) != 0)
    return false;
  SetCloseOnExec(fileno(log_file_));
  fseek(log_file_, 0, SEEK_END);
  if (ftell(log_file_) == 0) {
    if (fprintf(log_file_, kFileSignature, kCurrentVersion) < 0)
      return false;
  }
  return true;
}

namespace {

// Reads lines from a FILE in large chunks.
struct LineReader {
  explicit LineReader(FILE* file)
      : file_(file), buf_end_(buf_), line_start_(buf_), line_end_(nullptr) {
    memset(buf_, 0, sizeof(buf_));
  }

  bool ReadLine(char** line_start, char** line_end) {
    if (line_start_ >= buf_end_ || !line_end_) {
      // Buffer empty, refill.
      size_t size_read = fread(buf_, 1, sizeof(buf_), file_);
      if (!size_read)
        return false;
      line_start_ = buf_;
      buf_end_ = buf_ + size_read;
    } else {
      // Advance to next line in buffer.
      line_start_ = line_end_ + 1;
    }

    line_end_ = (char*)memchr(line_start_, '\n', buf_end_ - line_start_);
    if (!line_end_) {
      // No newline. Move rest of data to start of buffer, fill rest.
      size_t already_consumed = line_start_ - buf_;
      size_t size_rest = (buf_end_ - buf_) - already_consumed;
      memmove(buf_, line_start_, size_rest);

      size_t read = fread(buf_ + size_rest, 1, sizeof(buf_) - size_rest, file_);
      buf_end_ = buf_ + size_rest + read;
      line_start_ = buf_;
      line_end_ = (char*)memchr(line_start_, '\n', buf_end_ - line_start_);
    }

    *line_start = line_start_;
    *line_end = line_end_;
    return true;
  }

 private:
  FILE* file_;
  char buf_[256 << 10];
  char* buf_end_;
  char* line_start_;
  char* line_end_;
};

}  // namespace

LoadStatus BuildLog::Load(const std::string& path, std::string* err) {
  METRIC_RECORD(".ninja_log load");
  FILE* file = fopen(path.c_str(), "r");
  if (!file) {
    if (errno == ENOENT)
      return LOAD_NOT_FOUND;
    *err = strerror(errno);
    return LOAD_ERROR;
  }

  int log_version = 0;
  int unique_entry_count = 0;
  int total_entry_count = 0;

  LineReader* reader = new LineReader(file);
  char* line_start = nullptr;
  char* line_end = nullptr;
  while (reader->ReadLine(&line_start, &line_end)) {
    if (!log_version) {
      sscanf(line_start, kFileSignature, &log_version);

      bool invalid_log_version = false;
      if (log_version < kOldestSupportedVersion) {
        invalid_log_version = true;
        *err = "build log version is too old; starting over";
      } else if (log_version > kCurrentVersion) {
        invalid_log_version = true;
        *err = "build log version is too new; starting over";
      }
      if (invalid_log_version) {
        fclose(file);
        delete reader;
        unlink(path.c_str());
        return LOAD_NOT_FOUND;
      }
    }

    if (!line_end)
      continue;

    const char kFieldSeparator = '\t';

    char* start = line_start;
    char* end = (char*)memchr(start, kFieldSeparator, line_end - start);
    if (!end)
      continue;
    *end = 0;

    int start_time = 0, end_time = 0;
    TimeStamp mtime = 0;

    start_time = atoi(start);
    start = end + 1;

    end = (char*)memchr(start, kFieldSeparator, line_end - start);
    if (!end)
      continue;
    *end = 0;
    end_time = atoi(start);
    start = end + 1;

    end = (char*)memchr(start, kFieldSeparator, line_end - start);
    if (!end)
      continue;
    *end = 0;
    mtime = strtoll(start, nullptr, 10);
    start = end + 1;

    end = (char*)memchr(start, kFieldSeparator, line_end - start);
    if (!end)
      continue;
    std::string output(start, end - start);

    start = end + 1;
    end = line_end;

    LogEntry* entry = LookupByOutput(output);
    if (!entry) {
      entry = Insert(output);
      ++unique_entry_count;
    }
    ++total_entry_count;

    entry->start_time = start_time;
    entry->end_time = end_time;
    entry->mtime = mtime;
    char c = *end;
    *end = '\0';
    entry->command_hash = (uint64_t)strtoull(start, nullptr, 16);
    *end = c;
  }
  fclose(file);
  delete reader;

  if (!line_start)
    return LOAD_SUCCESS;  // file was empty

  int kMinCompactionEntryCount = 100;
  int kCompactionRatio = 3;
  if (log_version < kCurrentVersion) {
    needs_recompaction_ = true;
  } else if (total_entry_count > kMinCompactionEntryCount &&
             total_entry_count > unique_entry_count * kCompactionRatio) {
    needs_recompaction_ = true;
  }

  return LOAD_SUCCESS;
}

bool BuildLog::WriteEntry(FILE* f, const LogEntry& entry) {
  return fprintf(f, "%d\t%d\t%" PRId64 "\t%s\t%" PRIx64 "\n", entry.start_time,
                 entry.end_time, entry.mtime, entry.output.c_str(),
                 entry.command_hash) > 0;
}

bool BuildLog::Recompact(const std::string& path, const BuildLogUser& user,
                         std::string* err) {
  METRIC_RECORD(".ninja_log recompact");

  Close();
  std::string temp_path = path + ".recompact";
  FILE* f = fopen(temp_path.c_str(), "wb");
  if (!f) {
    *err = strerror(errno);
    return false;
  }

  if (fprintf(f, kFileSignature, kCurrentVersion) < 0) {
    *err = strerror(errno);
    fclose(f);
    return false;
  }

  std::vector<std::string> dead_outputs;
  for (LogEntry* e : order_) {
    if (user.IsPathDead(e->output)) {
      dead_outputs.push_back(e->output);
      continue;
    }
    if (!WriteEntry(f, *e)) {
      *err = strerror(errno);
      fclose(f);
      return false;
    }
  }

  for (const std::string& d : dead_outputs)
    Erase(d);

  fclose(f);
  if (unlink(path.c_str()) < 0) {
    *err = strerror(errno);
    return false;
  }

  if (rename(temp_path.c_str(), path.c_str()) < 0) {
    *err = strerror(errno);
    return false;
  }

  return true;
}

bool BuildLog::Restat(const std::string& path,
                      const DiskInterface& disk_interface, int output_count,
                      char** outputs, std::string* err) {
  METRIC_RECORD(".ninja_log restat");

  Close();
  std::string temp_path = path + ".restat";
  FILE* f = fopen(temp_path.c_str(), "wb");
  if (!f) {
    *err = strerror(errno);
    return false;
  }

  if (fprintf(f, kFileSignature, kCurrentVersion) < 0) {
    *err = strerror(errno);
    fclose(f);
    return false;
  }
  for (LogEntry* e : order_) {
    bool skip = output_count > 0;
    for (int j = 0; j < output_count; ++j) {
      if (e->output == outputs[j]) {
        skip = false;
        break;
      }
    }
    if (!skip) {
      const TimeStamp mtime = disk_interface.Stat(e->output, err);
      if (mtime == -1) {
        fclose(f);
        return false;
      }
      e->mtime = mtime;
    }

    if (!WriteEntry(f, *e)) {
      *err = strerror(errno);
      fclose(f);
      return false;
    }
  }

  fclose(f);
  if (unlink(path.c_str()) < 0) {
    *err = strerror(errno);
    return false;
  }

  if (rename(temp_path.c_str(), path.c_str()) < 0) {
    *err = strerror(errno);
    return false;
  }

  return true;
}
