#include "deps_log.h"

#include <assert.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>

#include "graph.h"
#include "metrics.h"
#include "util.h"

// File layout: signature, int32 version, then records.  Each record starts
// with a uint32 size; the high bit marks a deps record, otherwise it is a
// path record (path, NUL padding to 4 bytes, uint32 checksum ~id).
static const char kFileSignature[] = "# ninjadeps\n";
static const size_t kFileSignatureSize = sizeof(kFileSignature) - 1;
static const int32_t kCurrentVersion = 4;
static const unsigned kMaxRecordSize = (1 << 19) - 1;

DepsLog::~DepsLog() { Close(); }

bool DepsLog::OpenForWrite(const std::string& path, std::string* err) {
  if (needs_recompaction_) {
    if (!Recompact(path, err))
      return false;
  }
  assert(!file_);
  file_path_ = path;
  return true;
}

bool DepsLog::RecordDeps(Node* node, TimeStamp mtime,
                         const std::vector<Node*>& nodes) {
  return RecordDeps(node, mtime, (int)nodes.size(),
                    nodes.empty() ? nullptr : (Node* const*)&nodes.front());
}

bool DepsLog::RecordDeps(Node* node, TimeStamp mtime, int node_count,
                         Node* const* nodes) {
  bool made_change = false;

  if (node->id() < 0) {
    if (!RecordId(node))
      return false;
    made_change = true;
  }
  for (int i = 0; i < node_count; ++i) {
    if (nodes[i]->id() < 0) {
      if (!RecordId(nodes[i]))
        return false;
      made_change = true;
    }
  }

  if (!made_change) {
    Deps* deps = GetDeps(node);
    if (!deps || deps->mtime != mtime || deps->node_count != node_count) {
      made_change = true;
    } else {
      for (int i = 0; i < node_count; ++i) {
        if (deps->nodes[i] != nodes[i]) {
          made_change = true;
          break;
        }
      }
    }
  }

  if (!made_change)
    return true;

  unsigned size = 4 * (1 + 2 + node_count);
  if (size > kMaxRecordSize) {
    errno = ERANGE;
    return false;
  }

  if (!OpenForWriteIfNeeded())
    return false;
  size |= 0x80000000;
  if (fwrite(&size, 4, 1, file_) < 1)
    return false;
  int id = node->id();
  if (fwrite(&id, 4, 1, file_) < 1)
    return false;
  uint32_t mtime_part = static_cast<uint32_t>(mtime & 0xffffffff);
  if (fwrite(&mtime_part, 4, 1, file_) < 1)
    return false;
  mtime_part = static_cast<uint32_t>((mtime >> 32) & 0xffffffff);
  if (fwrite(&mtime_part, 4, 1, file_) < 1)
    return false;
  for (int i = 0; i < node_count; ++i) {
    id = nodes[i]->id();
    if (fwrite(&id, 4, 1, file_) < 1)
      return false;
  }
  if (fflush(file_) != 0)
    return false;

  Deps* deps = new Deps(mtime, node_count);
  for (int i = 0; i < node_count; ++i)
    deps->nodes[i] = nodes[i];
  UpdateDeps(node->id(), deps);

  return true;
}

void DepsLog::Close() {
  OpenForWriteIfNeeded();  // create the file even if nothing was recorded
  if (file_)
    fclose(file_);
  file_ = nullptr;
}

LoadStatus DepsLog::Load(const std::string& path, State* state,
                         std::string* err) {
  METRIC_RECORD(".ninja_deps load");
  char buf[kMaxRecordSize + 1];
  FILE* f = fopen(path.c_str(), "rb");
  if (!f) {
    if (errno == ENOENT)
      return LOAD_NOT_FOUND;
    *err = strerror(errno);
    return LOAD_ERROR;
  }

  bool valid_header = true;
  int version = 0;
  if (!fgets(buf, sizeof(buf), f) || fread(&version, 4, 1, f) < 1)
    valid_header = false;
  if (!valid_header || strcmp(buf, kFileSignature) != 0 ||
      version != kCurrentVersion) {
    if (version == 1)
      *err = "deps log version change; rebuilding";
    else
      *err = "bad deps log signature or version; starting over";
    fclose(f);
    unlink(path.c_str());
    return LOAD_SUCCESS;
  }

  long offset = ftell(f);
  bool read_failed = false;
  int unique_dep_record_count = 0;
  int total_dep_record_count = 0;
  for (;;) {
    offset = ftell(f);
    unsigned size;
    if (fread(&size, sizeof(size), 1, f) < 1) {
      if (!feof(f))
        read_failed = true;
      break;
    }
    bool is_deps = (size >> 31) != 0;
    size = size & 0x7FFFFFFF;

    if (size > kMaxRecordSize || fread(buf, size, 1, f) < 1) {
      read_failed = true;
      break;
    }

    if (is_deps) {
      if ((size % 4) != 0 || size < 12) {
        read_failed = true;
        break;
      }
      int* deps_data = reinterpret_cast<int*>(buf);
      int out_id = deps_data[0];
      TimeStamp mtime =
          (TimeStamp)(((uint64_t)(unsigned int)deps_data[2] << 32) |
                      (uint64_t)(unsigned int)deps_data[1]);
      deps_data += 3;
      int deps_count = (size / 4) - 3;

      if (out_id < 0 || out_id >= (int)nodes_.size() || !nodes_[out_id]) {
        read_failed = true;
        break;
      }
      for (int i = 0; i < deps_count; ++i) {
        int node_id = deps_data[i];
        if (node_id < 0 || node_id >= (int)nodes_.size() || !nodes_[node_id]) {
          read_failed = true;
          break;
        }
      }
      if (read_failed)
        break;

      Deps* deps = new Deps(mtime, deps_count);
      for (int i = 0; i < deps_count; ++i)
        deps->nodes[i] = nodes_[deps_data[i]];

      total_dep_record_count++;
      if (!UpdateDeps(out_id, deps))
        ++unique_dep_record_count;
    } else {
      int path_size = size - 4;
      if (path_size <= 0) {
        read_failed = true;
        break;
      }
      // Up to 3 bytes of NUL padding.
      if (buf[path_size - 1] == '\0') --path_size;
      if (path_size > 0 && buf[path_size - 1] == '\0') --path_size;
      if (path_size > 0 && buf[path_size - 1] == '\0') --path_size;
      std::string_view subpath(buf, path_size);
      Node* node = state->GetNode(subpath, 0);

      // The checksum must match the record's index: a mismatch means two
      // ninja processes wrote concurrently.
      unsigned checksum = *reinterpret_cast<unsigned*>(buf + size - 4);
      int expected_id = ~checksum;
      int id = nodes_.size();
      if (id != expected_id || node->id() >= 0) {
        read_failed = true;
        break;
      }
      node->set_id(id);
      nodes_.push_back(node);
    }
  }

  if (read_failed) {
    // Truncate the file to the last fully-read record and continue.
    if (ferror(f))
      *err = strerror(ferror(f));
    else
      *err = "premature end of file";
    fclose(f);

    if (!Truncate(path, offset, err))
      return LOAD_ERROR;

    *err += "; recovering";
    return LOAD_SUCCESS;
  }

  fclose(f);

  int kMinCompactionEntryCount = 1000;
  int kCompactionRatio = 3;
  if (total_dep_record_count > kMinCompactionEntryCount &&
      total_dep_record_count > unique_dep_record_count * kCompactionRatio) {
    needs_recompaction_ = true;
  }

  return LOAD_SUCCESS;
}

DepsLog::Deps* DepsLog::GetDeps(Node* node) {
  if (node->id() < 0 || node->id() >= (int)deps_.size())
    return nullptr;
  return deps_[node->id()];
}

Node* DepsLog::GetFirstReverseDepsNode(Node* node) {
  for (size_t id = 0; id < deps_.size(); ++id) {
    Deps* deps = deps_[id];
    if (!deps)
      continue;
    for (int i = 0; i < deps->node_count; ++i) {
      if (deps->nodes[i] == node)
        return nodes_[id];
    }
  }
  return nullptr;
}

bool DepsLog::Recompact(const std::string& path, std::string* err) {
  METRIC_RECORD(".ninja_deps recompact");

  Close();
  std::string temp_path = path + ".recompact";

  unlink(temp_path.c_str());

  DepsLog new_log;
  if (!new_log.OpenForWrite(temp_path, err))
    return false;

  // Ids are reassigned in the new log.
  for (Node* n : nodes_)
    n->set_id(-1);

  for (int old_id = 0; old_id < (int)deps_.size(); ++old_id) {
    Deps* deps = deps_[old_id];
    if (!deps)
      continue;

    if (!IsDepsEntryLiveFor(nodes_[old_id]))
      continue;

    if (!new_log.RecordDeps(nodes_[old_id], deps->mtime, deps->node_count,
                            deps->nodes)) {
      new_log.Close();
      return false;
    }
  }

  new_log.Close();

  deps_.swap(new_log.deps_);
  nodes_.swap(new_log.nodes_);

  if (unlink(path.c_str()) < 0) {
    *err = strerror(errno);
    return false;
  }

  if (rename(temp_path.c_str(), path.c_str()) < 0) {
    *err = strerror(errno);
    return false;
  }

  return true;
}

bool DepsLog::IsDepsEntryLiveFor(const Node* node) {
  return node->in_edge() && !node->in_edge()->GetBinding("deps").empty();
}

bool DepsLog::UpdateDeps(int out_id, Deps* deps) {
  if (out_id >= (int)deps_.size())
    deps_.resize(out_id + 1);

  bool delete_old = deps_[out_id] != nullptr;
  if (delete_old)
    delete deps_[out_id];
  deps_[out_id] = deps;
  return delete_old;
}

bool DepsLog::RecordId(Node* node) {
  int path_size = node->path().size();
  assert(path_size > 0);
  int padding = (4 - path_size % 4) % 4;

  unsigned size = path_size + padding + 4;
  if (size > kMaxRecordSize) {
    errno = ERANGE;
    return false;
  }

  if (!OpenForWriteIfNeeded())
    return false;
  if (fwrite(&size, 4, 1, file_) < 1)
    return false;
  if (fwrite(node->path().data(), path_size, 1, file_) < 1)
    return false;
  if (padding && fwrite("\0\0", padding, 1, file_) < 1)
    return false;
  int id = nodes_.size();
  unsigned checksum = ~(unsigned)id;
  if (fwrite(&checksum, 4, 1, file_) < 1)
    return false;
  if (fflush(file_) != 0)
    return false;

  node->set_id(id);
  nodes_.push_back(node);

  return true;
}

bool DepsLog::OpenForWriteIfNeeded() {
  if (file_path_.empty())
    return true;
  file_ = fopen(file_path_.c_str(), "ab");
  if (!file_)
    return false;
  if (setvbuf(file_, nullptr, _IOFBF, kMaxRecordSize + 1) != 0)
    return false;
  SetCloseOnExec(fileno(file_));

  fseek(file_, 0, SEEK_END);

  if (ftell(file_) == 0) {
    if (fwrite(kFileSignature, kFileSignatureSize, 1, file_) < 1)
      return false;
    if (fwrite(&kCurrentVersion, 4, 1, file_) < 1)
      return false;
  }
  if (fflush(file_) != 0)
    return false;
  file_path_.clear();
  return true;
}
