// Parser for build.ninja files.
#ifndef NJ_MANIFEST_PARSER_H_
#define NJ_MANIFEST_PARSER_H_

#include <memory>
#include <string>
#include <vector>

#include "lexer.h"

struct BindingEnv;
struct EvalString;
struct FileReader;
struct State;

enum PhonyCycleAction {
  kPhonyCycleActionWarn,
  kPhonyCycleActionError,
};

struct ManifestParserOptions {
  PhonyCycleAction phony_cycle_action_ = kPhonyCycleActionWarn;
};

/// Shared base for manifest and dyndep parsers.
struct Parser {
  Parser(State* state, FileReader* file_reader)
      : state_(state), file_reader_(file_reader) {}
  virtual ~Parser() {}

  /// Load and parse a file.
  bool Load(const std::string& filename, std::string* err,
            Lexer* parent = nullptr);

 protected:
  bool ExpectToken(Lexer::Token expected, std::string* err);

  State* state_;
  FileReader* file_reader_;
  Lexer lexer_;

 private:
  virtual bool Parse(const std::string& filename, const std::string& input,
                     std::string* err) = 0;
};

struct ManifestParser : public Parser {
  ManifestParser(State* state, FileReader* file_reader,
                 ManifestParserOptions options = ManifestParserOptions());

  /// Parse a text string of input (used by tests).
  bool ParseTest(const std::string& input, std::string* err) {
    quiet_ = true;
    return Parse("input", input, err);
  }

 private:
  bool Parse(const std::string& filename, const std::string& input,
             std::string* err) override;

  bool ParsePool(std::string* err);
  bool ParseRule(std::string* err);
  bool ParseLet(std::string* key, EvalString* val, std::string* err);
  bool ParseEdge(std::string* err);
  bool ParseDefault(std::string* err);
  bool ParseFileInclude(bool new_scope, std::string* err);

  BindingEnv* env_;
  ManifestParserOptions options_;
  bool quiet_ = false;

  std::unique_ptr<ManifestParser> subparser_;
  std::vector<EvalString> ins_, outs_, validations_;
};

/// Parse "major.minor" out of a version string.
void ParseVersion(const std::string& version, int* major, int* minor);
/// Check a manifest's ninja_required_version against our own.
void CheckNinjaVersion(const std::string& version);

extern const char* kNinjaVersion;

#endif  // NJ_MANIFEST_PARSER_H_
