cat > manifest_parser.cc <<'EOF'
#include "manifest_parser.h"

#include <assert.h>
#include <stdio.h>
#include <stdlib.h>

#include <algorithm>

#include "disk_interface.h"
#include "graph.h"
#include "metrics.h"
#include "util.h"

const char* kNinjaVersion = "1.14.0.git";

void ParseVersion(const std::string& version, int* major, int* minor) {
  size_t end = version.find('.');
  *major = atoi(version.substr(0, end).c_str());
  *minor = 0;
  if (end != std::string::npos) {
    size_t start = end + 1;
    end = version.find('.', start);
    *minor = atoi(version.substr(start, end).c_str());
  }
}

void CheckNinjaVersion(const std::string& version) {
  int bin_major, bin_minor;
  ParseVersion(kNinjaVersion, &bin_major, &bin_minor);
  int file_major, file_minor;
  ParseVersion(version, &file_major, &file_minor);

  if (bin_major > file_major) {
    Warning("ninja executable version (%s) greater than build file "
            "ninja_required_version (%s); versions may be incompatible.",
            kNinjaVersion, version.c_str());
    return;
  }

  if ((bin_major == file_major && bin_minor < file_minor) ||
      bin_major < file_major) {
    Fatal("ninja version (%s) incompatible with build file "
          "ninja_required_version version (%s).",
          kNinjaVersion, version.c_str());
  }
}

bool Parser::Load(const std::string& filename, std::string* err,
                  Lexer* parent) {
  METRIC_RECORD_IF(".ninja parse", parent == nullptr);
  std::string contents;
  std::string read_err;
  if (file_reader_->ReadFile(filename, &contents, &read_err) !=
      FileReader::Okay) {
    *err = "loading '" + filename + "': " + read_err;
    if (parent)
      parent->Error(std::string(*err), err);
    return false;
  }
  return Parse(filename, contents, err);
}

bool Parser::ExpectToken(Lexer::Token expected, std::string* err) {
  Lexer::Token token = lexer_.ReadToken();
  if (token != expected) {
    std::string message = std::string("expected ") + Lexer::TokenName(expected);
    message += std::string(", got ") + Lexer::TokenName(token);
    message += Lexer::TokenErrorHint(expected);
    return lexer_.Error(message, err);
  }
  return true;
}

ManifestParser::ManifestParser(State* state, FileReader* file_reader,
                               ManifestParserOptions options)
    : Parser(state, file_reader), options_(options) {
  env_ = &state->bindings_;
}

bool ManifestParser::Parse(const std::string& filename,
                           const std::string& input, std::string* err) {
  lexer_.Start(filename, input);

  for (;;) {
    Lexer::Token token = lexer_.ReadToken();
    switch (token) {
      case Lexer::POOL:
        if (!ParsePool(err))
          return false;
        break;
      case Lexer::BUILD:
        if (!ParseEdge(err))
          return false;
        break;
      case Lexer::RULE:
        if (!ParseRule(err))
          return false;
        break;
      case Lexer::DEFAULT:
        if (!ParseDefault(err))
          return false;
        break;
      case Lexer::IDENT: {
        lexer_.UnreadToken();
        std::string name;
        EvalString let_value;
        if (!ParseLet(&name, &let_value, err))
          return false;
        std::string value = let_value.Evaluate(env_);
        // ninja_required_version is checked as soon as it is seen.
        if (name == "ninja_required_version") {
          CheckNinjaVersion(value);
          int major, minor;
          ParseVersion(value, &major, &minor);
          lexer_.set_allow_newline_escape(major > 1 ||
                                          (major == 1 && minor >= 14));
        }
        env_->AddBinding(name, value);
        break;
      }
      case Lexer::INCLUDE:
        if (!ParseFileInclude(false, err))
          return false;
        break;
      case Lexer::SUBNINJA:
        if (!ParseFileInclude(true, err))
          return false;
        break;
      case Lexer::ERROR:
        return lexer_.Error(lexer_.DescribeLastError(), err);
      case Lexer::TEOF:
        return true;
      case Lexer::NEWLINE:
        break;
      default:
        return lexer_.Error(std::string("unexpected ") + Lexer::TokenName(token),
                            err);
    }
  }
  return false;  // not reached
}

bool ManifestParser::ParsePool(std::string* err) {
  std::string name;
  if (!lexer_.ReadIdent(&name))
    return lexer_.Error("expected pool name", err);

  if (!ExpectToken(Lexer::NEWLINE, err))
    return false;

  if (state_->LookupPool(name) != nullptr)
    return lexer_.Error("duplicate pool '" + name + "'", err);

  int depth = -1;

  while (lexer_.PeekToken(Lexer::INDENT)) {
    std::string key;
    EvalString value;
    if (!ParseLet(&key, &value, err))
      return false;

    if (key == "depth") {
      std::string depth_string = value.Evaluate(env_);
      depth = atol(depth_string.c_str());
      if (depth < 0)
        return lexer_.Error("invalid pool depth", err);
    } else {
      return lexer_.Error("unexpected variable '" + key + "'", err);
    }
  }

  if (depth < 0)
    return lexer_.Error("expected 'depth =' line", err);

  state_->AddPool(new Pool(name, depth));
  return true;
}

bool ManifestParser::ParseRule(std::string* err) {
  std::string name;
  if (!lexer_.ReadIdent(&name))
    return lexer_.Error("expected rule name", err);

  if (!ExpectToken(Lexer::NEWLINE, err))
    return false;

  if (env_->LookupRuleCurrentScope(name) != nullptr)
    return lexer_.Error("duplicate rule '" + name + "'", err);

  std::unique_ptr<Rule> rule(new Rule(name));

  while (lexer_.PeekToken(Lexer::INDENT)) {
    std::string key;
    EvalString value;
    if (!ParseLet(&key, &value, err))
      return false;

    if (Rule::IsReservedBinding(key)) {
      rule->AddBinding(key, value);
    } else {
      return lexer_.Error("unexpected variable '" + key + "'", err);
    }
  }

  if (rule->HasNonEmptyBinding("rspfile") !=
      rule->HasNonEmptyBinding("rspfile_content")) {
    return lexer_.Error("rspfile and rspfile_content need to be both specified",
                        err);
  }

  if (!rule->HasNonEmptyBinding("command"))
    return lexer_.Error("expected 'command =' line", err);

  env_->AddRule(std::move(rule));
  return true;
}

bool ManifestParser::ParseLet(std::string* key, EvalString* value,
                              std::string* err) {
  if (!lexer_.ReadIdent(key))
    return lexer_.Error("expected variable name", err);
  if (!ExpectToken(Lexer::EQUALS, err))
    return false;
  if (!lexer_.ReadVarValue(value, err))
    return false;
  return true;
}

bool ManifestParser::ParseDefault(std::string* err) {
  EvalString eval;
  if (!lexer_.ReadPath(&eval, err))
    return false;
  if (eval.empty())
    return lexer_.Error("expected target name", err);

  do {
    std::string path = eval.Evaluate(env_);
    if (path.empty())
      return lexer_.Error("empty path", err);
    uint64_t slash_bits;
    CanonicalizePath(&path, &slash_bits);
    std::string default_err;
    if (!state_->AddDefault(path, &default_err))
      return lexer_.Error(default_err, err);

    eval.Clear();
    if (!lexer_.ReadPath(&eval, err))
      return false;
  } while (!eval.empty());

  return ExpectToken(Lexer::NEWLINE, err);
}

bool ManifestParser::ParseEdge(std::string* err) {
  ins_.clear();
  outs_.clear();
  validations_.clear();

  {
    EvalString out;
    if (!lexer_.ReadPath(&out, err))
      return false;
    while (!out.empty()) {
      outs_.push_back(std::move(out));
      out.Clear();
      if (!lexer_.ReadPath(&out, err))
        return false;
    }
  }

  int implicit_outs = 0;
  if (lexer_.PeekToken(Lexer::PIPE)) {
    for (;;) {
      EvalString out;
      if (!lexer_.ReadPath(&out, err))
        return false;
      if (out.empty())
        break;
      outs_.push_back(std::move(out));
      ++implicit_outs;
    }
  }

  if (outs_.empty())
    return lexer_.Error("expected path", err);

  if (!ExpectToken(Lexer::COLON, err))
    return false;

  std::string rule_name;
  if (!lexer_.ReadIdent(&rule_name))
    return lexer_.Error("expected build command name", err);

  const Rule* rule = env_->LookupRule(rule_name);
  if (!rule)
    return lexer_.Error("unknown build rule '" + rule_name + "'", err);

  for (;;) {
    EvalString in;
    if (!lexer_.ReadPath(&in, err))
      return false;
    if (in.empty())
      break;
    ins_.push_back(std::move(in));
  }

  int implicit = 0;
  if (lexer_.PeekToken(Lexer::PIPE)) {
    for (;;) {
      EvalString in;
      if (!lexer_.ReadPath(&in, err))
        return false;
      if (in.empty())
        break;
      ins_.push_back(std::move(in));
      ++implicit;
    }
  }

  int order_only = 0;
  if (lexer_.PeekToken(Lexer::PIPE2)) {
    for (;;) {
      EvalString in;
      if (!lexer_.ReadPath(&in, err))
        return false;
      if (in.empty())
        break;
      ins_.push_back(std::move(in));
      ++order_only;
    }
  }

  if (lexer_.PeekToken(Lexer::PIPEAT)) {
    for (;;) {
      EvalString validation;
      if (!lexer_.ReadPath(&validation, err))
        return false;
      if (validation.empty())
        break;
      validations_.push_back(std::move(validation));
    }
  }

  if (!ExpectToken(Lexer::NEWLINE, err))
    return false;

  // Edge-level bindings get their own scope, but only when present.
  bool has_indent_token = lexer_.PeekToken(Lexer::INDENT);
  BindingEnv* env = has_indent_token ? new BindingEnv(env_) : env_;
  while (has_indent_token) {
    std::string key;
    EvalString val;
    if (!ParseLet(&key, &val, err))
      return false;

    env->AddBinding(key, val.Evaluate(env_));
    has_indent_token = lexer_.PeekToken(Lexer::INDENT);
  }

  Edge* edge = state_->AddEdge(rule);
  edge->env_ = env;

  std::string pool_name = edge->GetBinding("pool");
  if (!pool_name.empty()) {
    Pool* pool = state_->LookupPool(pool_name);
    if (pool == nullptr)
      return lexer_.Error("unknown pool name '" + pool_name + "'", err);
    edge->pool_ = pool;
  }

  edge->outputs_.reserve(outs_.size());
  for (size_t i = 0, e = outs_.size(); i != e; ++i) {
    std::string path = outs_[i].Evaluate(env);
    if (path.empty())
      return lexer_.Error("empty path", err);
    uint64_t slash_bits;
    CanonicalizePath(&path, &slash_bits);
    if (!state_->AddOut(edge, path, slash_bits, err)) {
      lexer_.Error(std::string(*err), err);
      return false;
    }
  }

  if (edge->outputs_.empty()) {
    // All outputs were already produced by other edges; drop this one.
    state_->edges_.pop_back();
    delete edge;
    return true;
  }
  edge->implicit_outs_ = implicit_outs;

  edge->inputs_.reserve(ins_.size());
  for (EvalString& i : ins_) {
    std::string path = i.Evaluate(env);
    if (path.empty())
      return lexer_.Error("empty path", err);
    uint64_t slash_bits;
    CanonicalizePath(&path, &slash_bits);
    state_->AddIn(edge, path, slash_bits);
  }
  edge->implicit_deps_ = implicit;
  edge->order_only_deps_ = order_only;

  edge->validations_.reserve(validations_.size());
  for (EvalString& v : validations_) {
    std::string path = v.Evaluate(env);
    if (path.empty())
      return lexer_.Error("empty path", err);
    uint64_t slash_bits;
    CanonicalizePath(&path, &slash_bits);
    state_->AddValidation(edge, path, slash_bits);
  }

  if (options_.phony_cycle_action_ == kPhonyCycleActionWarn &&
      edge->maybe_phonycycle_diagnostic()) {
    // Old CMake versions wrote phony edges that list themselves as inputs;
    // drop the self reference.
    Node* out = edge->outputs_[0];
    auto new_end =
        std::remove(edge->inputs_.begin(), edge->inputs_.end(), out);
    if (new_end != edge->inputs_.end()) {
      edge->inputs_.erase(new_end, edge->inputs_.end());
      if (!quiet_) {
        Warning("phony target '%s' names itself as an input; "
                "ignoring [-w phonycycle=warn]",
                out->path().c_str());
      }
    }
  }

  // The dyndep binding, if any, must name one of the edge's inputs.
  std::string dyndep = edge->GetUnescapedDyndep();
  if (!dyndep.empty()) {
    uint64_t slash_bits;
    CanonicalizePath(&dyndep, &slash_bits);
    edge->dyndep_ = state_->GetNode(dyndep, slash_bits);
    edge->dyndep_->set_dyndep_pending(true);
    auto dgi =
        std::find(edge->inputs_.begin(), edge->inputs_.end(), edge->dyndep_);
    if (dgi == edge->inputs_.end())
      return lexer_.Error("dyndep '" + dyndep + "' is not an input", err);
  }

  return true;
}

bool ManifestParser::ParseFileInclude(bool new_scope, std::string* err) {
  EvalString eval;
  if (!lexer_.ReadPath(&eval, err))
    return false;
  std::string path = eval.Evaluate(env_);

  if (subparser_ == nullptr)
    subparser_.reset(new ManifestParser(state_, file_reader_, options_));
  if (new_scope)
    subparser_->env_ = new BindingEnv(env_);
  else
    subparser_->env_ = env_;

  if (!subparser_->Load(path, err, &lexer_))
    return false;

  if (!ExpectToken(Lexer::NEWLINE, err))
    return false;

  return true;
}
