cat > dyndep_parser.cc <<'EOF'
#include "dyndep_parser.h"

#include <vector>

#include "dyndep.h"
#include "graph.h"
#include "util.h"

bool DyndepParser::Parse(const std::string& filename, const std::string& input,
                         std::string* err) {
  lexer_.Start(filename, input);

  bool have_dyndep_version = false;

  for (;;) {
    Lexer::Token token = lexer_.ReadToken();
    switch (token) {
      case Lexer::BUILD: {
        if (!have_dyndep_version)
          return lexer_.Error("expected 'ninja_dyndep_version = ...'", err);
        if (!ParseEdge(err))
          return false;
        break;
      }
      case Lexer::IDENT: {
        lexer_.UnreadToken();
        if (have_dyndep_version)
          return lexer_.Error(
              std::string("unexpected ") + Lexer::TokenName(token), err);
        if (!ParseDyndepVersion(err))
          return false;
        have_dyndep_version = true;
        break;
      }
      case Lexer::ERROR:
        return lexer_.Error(lexer_.DescribeLastError(), err);
      case Lexer::TEOF:
        if (!have_dyndep_version)
