bool DyndepLoader::LoadDyndeps(Node* node, DyndepFile* ddf,
                               std::string* err) const {
  // The file is being loaded now, so it is no longer pending.
  node->set_dyndep_pending(false);

  explanations_.Record(node, "loading dyndep file '%s'", node->path().c_str());

  if (!LoadDyndepFile(node, ddf, err))
    return false;

  // Update each edge that names this node in its dyndep binding.
  for (Edge* edge : node->out_edges()) {
    if (edge->dyndep_ != node)
      continue;

    auto ddi = ddf->find(edge);
    if (ddi == ddf->end()) {
      *err = ("'" + edge->outputs_[0]->path() +
              "' "
              "not mentioned in its dyndep file "
              "'" +
              node->path() + "'");
      return false;
    }

    ddi->second.used_ = true;
    Dyndeps const& dyndeps = ddi->second;
    if (!UpdateEdge(edge, &dyndeps, err))
      return false;
  }

  // Reject extra outputs in the dyndep file.
  for (auto& oe : *ddf) {
    if (!oe.second.used_) {
      Edge* const edge = oe.first;
      *err = ("dyndep file '" + node->path() +
              "' mentions output "
              "'" +
              edge->outputs_[0]->path() +
              "' whose build statement "
              "does not have a dyndep binding for the file");
      return false;
    }
  }

  return true;
}

bool DyndepLoader::UpdateEdge(Edge* edge, Dyndeps const* dyndeps,
                              std::string* err) const {
  // The edge has its own binding scope because it has a dyndep binding.
  if (dyndeps->restat_)
    edge->env_->AddBinding("restat", "1");

  edge->outputs_.insert(edge->outputs_.end(),
                        dyndeps->implicit_outputs_.begin(),
                        dyndeps->implicit_outputs_.end());
  edge->implicit_outs_ += dyndeps->implicit_outputs_.size();

  for (Node* n : dyndeps->implicit_outputs_) {
    if (Edge* old_in_edge = n->in_edge()) {
      // Only an edge made up by the deps loader may be replaced.
      if (!old_in_edge->generated_by_dep_loader_) {
        *err = "multiple rules generate " + n->path();
        return false;
      }
      old_in_edge->outputs_.clear();
    }
    n->set_in_edge(edge);
  }

  edge->inputs_.insert(edge->inputs_.end() - edge->order_only_deps_,
                       dyndeps->implicit_inputs_.begin(),
                       dyndeps->implicit_inputs_.end());
  edge->implicit_deps_ += dyndeps->implicit_inputs_.size();

  for (Node* n : dyndeps->implicit_inputs_)
    n->AddOutEdge(edge);

  return true;
}

