cat > clparser.cc <<'EOF'
#include "clparser.h"

#include <assert.h>
#include <string.h>

#include <algorithm>

#include "metrics.h"
#include "util.h"

static char ToLowerASCII(char c) {
  return (c >= 'A' && c <= 'Z') ? (c + ('a' - 'A')) : c;
}

std::string CLParser::FilterShowIncludes(const std::string& line,
                                         const std::string& deps_prefix) {
  const std::string kDepsPrefixEnglish = "Note: including file: ";
  const char* in = line.c_str();
  const char* end = in + line.size();
  const std::string& prefix =
      deps_prefix.empty() ? kDepsPrefixEnglish : deps_prefix;
  if (end - in > (int)prefix.size() &&
      memcmp(in, prefix.c_str(), (int)prefix.size()) == 0) {
    in += prefix.size();
    while (*in == ' ')
      ++in;
    return line.substr(in - line.c_str());
  }
  return "";
}

bool CLParser::IsSystemInclude(std::string path) {
  std::transform(path.begin(), path.end(), path.begin(), ToLowerASCII);
  return path.find("program files") != std::string::npos ||
         path.find("microsoft visual studio") != std::string::npos;
}

bool CLParser::FilterInputFilename(std::string line) {
  std::transform(line.begin(), line.end(), line.begin(), ToLowerASCII);
  return EndsWith(line, ".c") || EndsWith(line, ".cc") ||
         EndsWith(line, ".cxx") || EndsWith(line, ".cpp") ||
         EndsWith(line, ".c++");
}

bool CLParser::Parse(const std::string& output, const std::string& deps_prefix,
                     std::string* filtered_output, std::string* err) {
  METRIC_RECORD("CLParser::Parse");

  size_t start = 0;
  bool seen_show_includes = false;

  while (start < output.size()) {
    size_t end = output.find_first_of("\r\n", start);
    if (end == std::string::npos)
      end = output.size();
    std::string line = output.substr(start, end - start);

    std::string include = FilterShowIncludes(line, deps_prefix);
    if (!include.empty()) {
      seen_show_includes = true;
      std::string normalized = include;
      uint64_t slash_bits;
      CanonicalizePath(&normalized, &slash_bits);
      if (!IsSystemInclude(normalized))
        includes_.insert(normalized);
    } else if (!seen_show_includes && FilterInputFilename(line)) {
      // Drop the echoed input file name.
    } else {
      filtered_output->append(line);
      filtered_output->append("\n");
    }

    if (end < output.size() && output[end] == '\r')
      ++end;
    if (end < output.size() && output[end] == '\n')
      ++end;
    start = end;
  }

  return true;
}
