#include "subprocess.h"

#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <spawn.h>
#include <stdio.h>
#include <string.h>
#include <sys/wait.h>
#include <unistd.h>

#include "util.h"

extern char** environ;

Subprocess::Subprocess(bool use_console)
    : fd_(-1), pid_(-1), use_console_(use_console) {}

Subprocess::~Subprocess() {
  if (fd_ >= 0)
    close(fd_);
  // Reap the child if it was forgotten.
  if (pid_ != -1)
    Finish();
}

bool Subprocess::Start(SubprocessSet* set, const std::string& command) {
  int subproc_stdout_fd = -1;
  if (use_console_) {
    fd_ = -1;
  } else {
    int output_pipe[2];
    if (pipe(output_pipe) < 0)
      Fatal("pipe: %s", strerror(errno));
    fd_ = output_pipe[0];
    subproc_stdout_fd = output_pipe[1];
    SetCloseOnExec(fd_);
  }

  posix_spawn_file_actions_t action;
  int err = posix_spawn_file_actions_init(&action);
  if (err != 0)
    Fatal("posix_spawn_file_actions_init: %s", strerror(err));

  if (!use_console_) {
    err = posix_spawn_file_actions_addclose(&action, fd_);
    if (err != 0)
      Fatal("posix_spawn_file_actions_addclose: %s", strerror(err));
  }

  posix_spawnattr_t attr;
  err = posix_spawnattr_init(&attr);
  if (err != 0)
    Fatal("posix_spawnattr_init: %s", strerror(err));

  short flags = 0;

  flags |= POSIX_SPAWN_SETSIGMASK;
  err = posix_spawnattr_setsigmask(&attr, &set->old_mask_);
  if (err != 0)
    Fatal("posix_spawnattr_setsigmask: %s", strerror(err));

  if (!use_console_) {
    // Own process group, so that Ctrl-C at the terminal doesn't reach it.
    flags |= POSIX_SPAWN_SETPGROUP;

    err = posix_spawn_file_actions_addopen(&action, 0, "/dev/null", O_RDONLY,
                                           0);
    if (err != 0)
      Fatal("posix_spawn_file_actions_addopen: %s", strerror(err));

    err = posix_spawn_file_actions_adddup2(&action, subproc_stdout_fd, 1);
    if (err != 0)
      Fatal("posix_spawn_file_actions_adddup2: %s", strerror(err));
    err = posix_spawn_file_actions_adddup2(&action, subproc_stdout_fd, 2);
    if (err != 0)
      Fatal("posix_spawn_file_actions_adddup2: %s", strerror(err));
    err = posix_spawn_file_actions_addclose(&action, subproc_stdout_fd);
    if (err != 0)
      Fatal("posix_spawn_file_actions_addclose: %s", strerror(err));
  }

  err = posix_spawnattr_setflags(&attr, flags);
  if (err != 0)
    Fatal("posix_spawnattr_setflags: %s", strerror(err));

  const char* spawned_args[] = {"/bin/sh", "-c", command.c_str(), nullptr};
  err = posix_spawn(&pid_, "/bin/sh", &action, &attr,
                    const_cast<char**>(spawned_args), environ);
  if (err != 0)
    Fatal("posix_spawn: %s", strerror(err));

  err = posix_spawnattr_destroy(&attr);
  if (err != 0)
    Fatal("posix_spawnattr_destroy: %s", strerror(err));
  err = posix_spawn_file_actions_destroy(&action);
  if (err != 0)
    Fatal("posix_spawn_file_actions_destroy: %s", strerror(err));

  if (!use_console_)
    close(subproc_stdout_fd);
  return true;
}

void Subprocess::OnPipeReady() {
  char buf[4 << 10];
  ssize_t len = read(fd_, buf, sizeof(buf));
  if (len > 0) {
    buf_.append(buf, len);
  } else {
    if (len < 0) {
      if (errno == EINTR || errno == EAGAIN)
        return;
      Fatal("read: %s", strerror(errno));
    }
    close(fd_);
    fd_ = -1;
  }
}

bool Subprocess::TryReap() {
  if (reaped_)
    return true;
  if (pid_ == -1)
    return true;
  int status;
  pid_t r = waitpid(pid_, &status, WNOHANG);
  if (r == pid_) {
    reaped_ = true;
    wait_status_ = status;
    return true;
  }
  return false;
}

bool Subprocess::Done() const {
  if (use_console_)
    return reaped_;
  return fd_ == -1;
}

ExitStatus Subprocess::Finish() {
  assert(pid_ != -1);
  int status;
  if (reaped_) {
    status = wait_status_;
  } else {
