// Client side of the GNU make jobserver protocol (FIFO mode only).
#ifndef NJ_JOBSERVER_H_
#define NJ_JOBSERVER_H_

#include <string>

struct JobserverConfig {
  enum Mode { kModeNone, kModePipe, kModePosixFifo, kModeWin32Semaphore };
  Mode mode = kModeNone;
  std::string path;
  bool HasMode() const { return mode != kModeNone; }
};

/// Parse a MAKEFLAGS value.  Returns false (with |err|) on malformed input.
bool ParseJobserverMakeFlags(const char* makeflags, JobserverConfig* config,
                             std::string* err);

class JobserverClient {
 public:
  ~JobserverClient();

  /// Create a client for |config|; returns null and sets |err| on failure.
  static JobserverClient* Create(const JobserverConfig& config,
                                 std::string* err);

  /// Returns a slot value: 0 for the implicit slot, 1..256 for an explicit
  /// token (byte value + 1), or -1 if no slot is available.
  int TryAcquire();
  void Release(int slot);

 private:
  JobserverClient() {}
  bool InitWithFifo(const std::string& path, std::string* err);

  int read_fd_ = -1;
  int write_fd_ = -1;
  bool has_implicit_slot_ = true;
};

#endif  // NJ_JOBSERVER_H_
