#include "jobserver.h"

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include <vector>

static bool StartsWith(const std::string& s, const char* prefix) {
  size_t n = strlen(prefix);
  return s.size() >= n && s.compare(0, n, prefix) == 0;
}

bool ParseJobserverMakeFlags(const char* makeflags, JobserverConfig* config,
                             std::string* err) {
  *config = JobserverConfig();
  if (!makeflags || !makeflags[0])
    return true;

  // Split into space or tab separated words.
  std::vector<std::string> args;
  const char* p = makeflags;
  while (*p) {
    const char* next = strpbrk(p, " \t");
    if (!next) {
      args.emplace_back(p);
      break;
    }
    if (next > p)
      args.emplace_back(p, next - p);
    p = next + 1;
  }

  for (const std::string& arg : args) {
    if (StartsWith(arg, "--jobserver-auth=")) {
      std::string value = arg.substr(17);
      if (StartsWith(value, "fifo:")) {
        config->mode = JobserverConfig::kModePosixFifo;
        config->path = value.substr(5);
      } else {
        int read_fd, write_fd;
        if (sscanf(value.c_str(), "%d,%d", &read_fd, &write_fd) == 2) {
          if (read_fd < 0 || write_fd < 0) {
            config->mode = JobserverConfig::kModeNone;
            config->path.clear();
          } else {
            config->mode = JobserverConfig::kModePipe;
            config->path.clear();
          }
        } else {
          config->mode = JobserverConfig::kModeWin32Semaphore;
          config->path = value;
        }
      }
    } else if (StartsWith(arg, "--jobserver-fds=")) {
      std::string value = arg.substr(16);
      int read_fd, write_fd;
      if (sscanf(value.c_str(), "%d,%d", &read_fd, &write_fd) != 2) {
        *err = "Invalid file descriptor pair [" + value + "]";
        return false;
      }
      config->mode = JobserverConfig::kModePipe;
      config->path.clear();
    }
  }
  return true;
}

JobserverClient::~JobserverClient() {
  if (write_fd_ >= 0)
    close(write_fd_);
  if (read_fd_ >= 0)
    close(read_fd_);
}

JobserverClient* JobserverClient::Create(const JobserverConfig& config,
                                         std::string* err) {
  if (config.mode == JobserverConfig::kModePosixFifo) {
    JobserverClient* client = new JobserverClient();
    if (!client->InitWithFifo(config.path, err)) {
      delete client;
      return nullptr;
    }
    return client;
  }
  *err = "Unsupported jobserver mode";
  return nullptr;
}

bool JobserverClient::InitWithFifo(const std::string& path, std::string* err) {
  if (path.empty()) {
    *err = "Empty fifo path";
    return false;
  }
  read_fd_ = open(path.c_str(), O_RDONLY | O_NONBLOCK | O_CLOEXEC);
  if (read_fd_ < 0) {
    *err = std::string("Error opening fifo for reading: ") + strerror(errno);
    return false;
  }
  struct stat st;
  if (fstat(read_fd_, &st) < 0 || !S_ISFIFO(st.st_mode)) {
    *err = "Not a fifo path: " + path;
    return false;
  }
  write_fd_ = open(path.c_str(), O_WRONLY | O_NONBLOCK | O_CLOEXEC);
  if (write_fd_ < 0) {
    *err = std::string("Error opening fifo for writing: ") + strerror(errno);
    return false;
  }
  return true;
}

int JobserverClient::TryAcquire() {
  if (has_implicit_slot_) {
    has_implicit_slot_ = false;
    return 0;
  }
  unsigned char c = 0;
  ssize_t ret;
  do {
    ret = read(read_fd_, &c, 1);
  } while (ret < 0 && errno == EINTR);
  if (ret == 1)
    return (int)c + 1;
  return -1;
}

void JobserverClient::Release(int slot) {
  if (slot < 0)
    return;
  if (slot == 0) {
    has_implicit_slot_ = true;
    return;
  }
  unsigned char c = (unsigned char)(slot - 1);
  ssize_t ret;
  do {
    ret = write(write_fd_, &c, 1);
  } while (ret < 0 && errno == EINTR);
  (void)ret;
}
