namespace {

/// A CommandRunner that doesn't actually run the commands.
struct DryRunCommandRunner : public CommandRunner {
  size_t CanRunMore() const override { return SIZE_MAX; }
  bool StartCommand(Edge* edge) override {
    finished_.push(edge);
    return true;
  }
  bool WaitForCommand(Result* result) override {
    if (finished_.empty())
      return false;
    result->status = ExitSuccess;
    result->edge = finished_.front();
    finished_.pop();
    return true;
  }

 private:
  std::queue<Edge*> finished_;
};

struct RealCommandRunner : public CommandRunner {
  RealCommandRunner(const BuildConfig& config, JobserverClient* jobserver)
      : config_(config), jobserver_(jobserver) {}
  ~RealCommandRunner() override { ClearJobTokens(); }

  size_t CanRunMore() const override;
  bool StartCommand(Edge* edge) override;
  bool WaitForCommand(Result* result) override;
  std::vector<Edge*> GetActiveEdges() override;
  void Abort() override;

  void ClearJobTokens() {
    if (jobserver_) {
      for (Edge* edge : GetActiveEdges()) {
        jobserver_->Release(edge->job_slot_);
        edge->job_slot_ = -1;
      }
    }
  }

  const BuildConfig& config_;
  SubprocessSet subprocs_;
  JobserverClient* jobserver_;
  std::map<const Subprocess*, Edge*> subproc_to_edge_;
};

std::vector<Edge*> RealCommandRunner::GetActiveEdges() {
  std::vector<Edge*> edges;
  for (auto& e : subproc_to_edge_)
    edges.push_back(e.second);
  return edges;
}

void RealCommandRunner::Abort() {
  ClearJobTokens();
  subprocs_.Clear();
}

size_t RealCommandRunner::CanRunMore() const {
  size_t subproc_number =
      subprocs_.running_.size() + subprocs_.finished_.size();

  int64_t capacity = (int64_t)config_.parallelism - (int64_t)subproc_number;

  if (jobserver_) {
    // Tokens limit parallelism instead.
    capacity = INT_MAX;
  }

  if (config_.max_load_average > 0.0f) {
    int load_capacity = config_.max_load_average - GetLoadAverage();
    if (load_capacity < capacity)
      capacity = load_capacity;
  }

  if (capacity < 0)
    capacity = 0;

  if (capacity == 0 && subprocs_.running_.empty())
    capacity = 1;  // Ensure that we make progress.

  return capacity;
}

bool RealCommandRunner::StartCommand(Edge* edge) {
  std::string command = edge->EvaluateCommand();
  Subprocess* subproc = subprocs_.Add(command, edge->use_console());
  if (!subproc)
    return false;
  subproc_to_edge_.insert(std::make_pair(subproc, edge));
  return true;
}

bool RealCommandRunner::WaitForCommand(Result* result) {
  Subprocess* subproc;
  while ((subproc = subprocs_.NextFinished()) == nullptr) {
    bool interrupted = subprocs_.DoWork();
    if (interrupted)
      return false;
  }

  result->status = subproc->Finish();
  result->output = subproc->GetOutput();

  auto e = subproc_to_edge_.find(subproc);
  result->edge = e->second;
  subproc_to_edge_.erase(e);

  delete subproc;
  return true;
}

}  // namespace

CommandRunner* CommandRunner::factory(const BuildConfig& config,
                                      JobserverClient* jobserver) {
  return new RealCommandRunner(config, jobserver);
}

Plan::Plan(Builder* builder)
    : builder_(builder), command_edges_(0), wanted_edges_(0) {}

void Plan::Reset() {
  command_edges_ = 0;
  wanted_edges_ = 0;
  ready_.clear();
  want_.clear();
}

bool Plan::AddTarget(const Node* target, std::string* err) {
  targets_.push_back(target);
  return AddSubTarget(target, nullptr, err, nullptr);
}

bool Plan::AddSubTarget(const Node* node, const Node* dependent,
                        std::string* err, EdgeSet* dyndep_walk) {
  Edge* edge = node->in_edge();
  if (!edge) {
    // A leaf: either a source file from the manifest (an error if missing)
    // or something discovered by a dep loader (nothing to do).
    if (node->dirty() && !node->generated_by_dep_loader()) {
      std::string referenced;
      if (dependent)
        referenced = ", needed by '" + dependent->path() + "',";
      *err = "'" + node->path() + "'" + referenced +
             " missing and no known rule to make it";
    }
    return false;
  }

  if (edge->outputs_ready())
    return false;  // Don't need to do anything.

  auto want_ins = want_.insert(std::make_pair(edge, kWantNothing));
  Want& want = want_ins.first->second;

  if (dyndep_walk && want == kWantToFinish)
    return false;  // Already-scheduled edge.

  if (node->dirty() && want == kWantNothing) {
    want = kWantToStart;
    EdgeWanted(edge);
  }

  if (dyndep_walk)
    dyndep_walk->insert(edge);

  if (!want_ins.second)
    return true;  // Inputs already processed.

  for (Node* in : edge->inputs_) {
    if (!AddSubTarget(in, node, err, dyndep_walk) && !err->empty())
      return false;
  }

  return true;
}

void Plan::EdgeWanted(const Edge* edge) {
  ++wanted_edges_;
  if (!edge->is_phony()) {
    ++command_edges_;
    if (builder_)
      builder_->status_->EdgeAddedToPlan(edge);
  }
}

Edge* Plan::FindWork() {
  if (ready_.empty())
    return nullptr;

  Edge* work = ready_.top();

  // In jobserver mode a token is needed before the edge can start.
  if (builder_ && builder_->jobserver_ && !work->is_phony()) {
    work->job_slot_ = builder_->jobserver_->TryAcquire();
    if (work->job_slot_ < 0)
      return nullptr;
  }

  ready_.pop();
  return work;
}

void Plan::ScheduleWork(WantMap::iterator want_e) {
  if (want_e->second == kWantToFinish) {
    // Already scheduled (e.g. shared order-only input).
    return;
  }
  assert(want_e->second == kWantToStart);
  want_e->second = kWantToFinish;

  Edge* edge = want_e->first;
  Pool* pool = edge->pool();
  if (pool->ShouldDelayEdge()) {
    pool->DelayEdge(edge);
    pool->RetrieveReadyEdges(&ready_);
  } else {
    pool->EdgeScheduled(*edge);
    ready_.push(edge);
  }
}

bool Plan::EdgeFinished(Edge* edge, EdgeResult result, std::string* err) {
  auto e = want_.find(edge);
  assert(e != want_.end());
  bool directly_wanted = e->second != kWantNothing;

  // This may free up delayed edges in the pool.
  if (directly_wanted)
    edge->pool()->EdgeFinished(*edge);
  edge->pool()->RetrieveReadyEdges(&ready_);

  if (builder_ && builder_->jobserver_ && edge->job_slot_ >= 0) {
    builder_->jobserver_->Release(edge->job_slot_);
    edge->job_slot_ = -1;
  }

  if (result != kEdgeSucceeded)
    return true;

  if (directly_wanted)
    --wanted_edges_;
  want_.erase(e);
  edge->outputs_ready_ = true;

  for (Node* o : edge->outputs_) {
    if (!NodeFinished(o, err))
      return false;
  }
  return true;
}

bool Plan::NodeFinished(Node* node, std::string* err) {
  // A finished dyndep file gets loaded now; that also updates the plan.
  if (node->dyndep_pending()) {
    assert(builder_ && "dyndep requires Plan to have a Builder");
    return builder_->LoadDyndeps(node, err);
  }

  // Copy: EdgeMaybeReady may append to out_edges via dyndep loading.
  std::vector<Edge*> out_edges = node->out_edges();
  for (Edge* oe : out_edges) {
    auto want_e = want_.find(oe);
    if (want_e == want_.end())
      continue;
    if (!EdgeMaybeReady(want_e, err))
      return false;
  }
  return true;
}

bool Plan::EdgeMaybeReady(WantMap::iterator want_e, std::string* err) {
  Edge* edge = want_e->first;
  if (edge->AllInputsReady()) {
    if (want_e->second != kWantNothing) {
      ScheduleWork(want_e);
    } else {
      // Not needed itself, but dependents may be.
      if (!EdgeFinished(edge, kEdgeSucceeded, err))
        return false;
    }
  }
  return true;
}

bool Plan::CleanNode(DependencyScan* scan, Node* node, std::string* err) {
  node->set_dirty(false);

  std::vector<Edge*> out_edges = node->out_edges();
  for (Edge* oe : out_edges) {
    auto want_e = want_.find(oe);
    if (want_e == want_.end() || want_e->second == kWantNothing)
      continue;

    // Don't clean edges that failed to load deps.
    if (oe->deps_missing_)
      continue;

    // If all non-order-only inputs are clean, outputs may now be clean too.
    auto begin = oe->inputs_.begin();
    auto end = oe->inputs_.end() - oe->order_only_deps_;
    if (std::find_if(begin, end, [](Node* n) { return n->dirty(); }) == end) {
      Node* most_recent_input = nullptr;
      for (auto i = begin; i != end; ++i) {
        if (!most_recent_input || (*i)->mtime() > most_recent_input->mtime())
          most_recent_input = *i;
      }

      bool outputs_dirty = false;
      if (!scan->RecomputeOutputsDirty(oe, most_recent_input, &outputs_dirty,
                                       err)) {
        return false;
      }
      if (!outputs_dirty) {
        for (Node* o : oe->outputs_) {
          if (!CleanNode(scan, o, err))
            return false;
        }

        want_e->second = kWantNothing;
        --wanted_edges_;
        if (!oe->is_phony()) {
          --command_edges_;
          if (builder_)
            builder_->status_->EdgeRemovedFromPlan(oe);
        }
      }
    }
  }
  return true;
}

bool Plan::DyndepsLoaded(DependencyScan* scan, const Node* node,
                         const DyndepFile& ddf, std::string* err) {
  // Recompute dirty state of everything downstream of the dyndep file.
  if (!RefreshDyndepDependents(scan, node, err))
    return false;

  // Edges already in the plan that got new dyndep information.
  std::vector<DyndepFile::const_iterator> dyndep_roots;
  for (auto oe = ddf.begin(); oe != ddf.end(); ++oe) {
    Edge* edge = oe->first;
    if (edge->outputs_ready())
      continue;
    auto want_e = want_.find(edge);
    if (want_e == want_.end())
      continue;
    dyndep_roots.push_back(oe);
  }

  // Walk the newly reachable portion of the graph.
  EdgeSet dyndep_walk;
  for (auto oe : dyndep_roots) {
    for (Node* i : oe->second.implicit_inputs_) {
      if (!AddSubTarget(i, oe->first->outputs_[0], err, &dyndep_walk) &&
          !err->empty())
        return false;
    }
  }

  // Out edges of this node that are in the plan.
  for (Edge* oe : node->out_edges()) {
    auto want_e = want_.find(oe);
    if (want_e == want_.end())
      continue;
    dyndep_walk.insert(want_e->first);
  }

  // See if any encountered edges are now ready.
  for (Edge* wi : dyndep_walk) {
    auto want_e = want_.find(wi);
    if (want_e == want_.end())
      continue;
    if (!EdgeMaybeReady(want_e, err))
      return false;
  }

  return true;
}

bool Plan::RefreshDyndepDependents(DependencyScan* scan, const Node* node,
                                   std::string* err) {
  std::set<Node*, NodeSeqLess> dependents;
  UnmarkDependents(node, &dependents);

  for (Node* n : dependents) {
    std::vector<Node*> validation_nodes;
    if (!scan->RecomputeDirty(n, &validation_nodes, err))
      return false;

    for (Node* v : validation_nodes) {
      if (Edge* in_edge = v->in_edge()) {
        if (!in_edge->outputs_ready() && !AddTarget(v, err))
          return false;
      }
    }
    if (!n->dirty())
      continue;

    // With dyndep information an output is now known to be dirty.
    Edge* edge = n->in_edge();
    assert(edge && !edge->outputs_ready());
    auto want_e = want_.find(edge);
    assert(want_e != want_.end());
    if (want_e->second == kWantNothing) {
      want_e->second = kWantToStart;
      EdgeWanted(edge);
    }
  }
  return true;
}

void Plan::UnmarkDependents(const Node* node,
                            std::set<Node*, NodeSeqLess>* dependents) {
  for (Edge* edge : node->out_edges()) {
    auto want_e = want_.find(edge);
    if (want_e == want_.end())
      continue;

    if (edge->mark_ != Edge::VisitNone) {
      edge->mark_ = Edge::VisitNone;
      for (Node* o : edge->outputs_) {
        if (dependents->insert(o).second)
          UnmarkDependents(o, dependents);
      }
    }
  }
}

namespace {

int64_t EdgeWeightHeuristic(Edge* edge) { return edge->is_phony() ? 0 : 1; }

}  // namespace

void Plan::ComputeCriticalPath() {
  METRIC_RECORD("ComputeCriticalPath");
  // Remove duplicate targets.
  std::vector<const Node*> unique_targets;
  {
    std::unordered_set<const Node*> seen;
    for (const Node* t : targets_)
      if (seen.insert(t).second)
        unique_targets.push_back(t);
  }

  // Back-propagate weights from the targets, breadth first.
  std::queue<Edge*> work_queue;
  std::unordered_set<const Edge*> active_edges;

  for (const Node* target : unique_targets) {
    if (Edge* in = target->in_edge()) {
      int64_t edge_weight = EdgeWeightHeuristic(in);
      in->set_critical_path_weight(
          std::max<int64_t>(edge_weight, in->critical_path_weight()));
      if (active_edges.insert(in).second)
        work_queue.push(in);
    }
  }

  while (!work_queue.empty()) {
    Edge* e = work_queue.front();
    work_queue.pop();
    // Allow re-processing if a dependent's weight gets raised later.
    active_edges.erase(e);

    for (const Node* input : e->inputs_) {
      Edge* in = input->in_edge();
      if (!in)
        continue;
      const int64_t edge_weight = EdgeWeightHeuristic(in);
      const int64_t proposed_weight = e->critical_path_weight() + edge_weight;
      if (proposed_weight > in->critical_path_weight()) {
        in->set_critical_path_weight(proposed_weight);
        if (active_edges.insert(in).second)
          work_queue.push(in);
      }
    }
  }
}

void Plan::ScheduleInitialEdges() {
  assert(ready_.empty());
  std::set<Pool*> pools;

  for (auto it = want_.begin(), end = want_.end(); it != end; ++it) {
    Edge* edge = it->first;
    Want want = it->second;
    if (want == kWantToStart && edge->AllInputsReady()) {
      Pool* pool = edge->pool();
      if (pool->ShouldDelayEdge()) {
        pool->DelayEdge(edge);
        pools.insert(pool);
      } else {
        ScheduleWork(it);
      }
    }
  }

  // Retrieve delayed edges only once, so higher priority ones come first.
  for (Pool* pool : pools)
    pool->RetrieveReadyEdges(&ready_);
}

void Plan::PrepareQueue() {
  ComputeCriticalPath();
  ScheduleInitialEdges();
}

void Plan::Dump() const {
  printf("pending: %d\n", (int)want_.size());
  for (auto& e : want_) {
    if (e.second != kWantNothing)
      printf("want ");
    e.first->Dump();
  }
  printf("ready: %d\n", (int)ready_.size());
}

Builder::Builder(State* state, const BuildConfig& config, BuildLog* build_log,
                 DepsLog* deps_log, DiskInterface* disk_interface,
                 Status* status, int64_t start_time_millis)
    : state_(state),
      config_(config),
      plan_(this),
      status_(status),
      start_time_millis_(start_time_millis),
      disk_interface_(disk_interface),
      explanations_(g_explaining ? new Explanations() : nullptr),
      scan_(state, build_log, deps_log, disk_interface,
            &config_.depfile_parser_options, explanations_.get()) {
  lock_file_path_ = ".ninja_lock";
  std::string build_dir = state_->bindings_.LookupVariable("builddir");
  if (!build_dir.empty())
    lock_file_path_ = build_dir + "/" + lock_file_path_;
  status_->SetExplanations(explanations_.get());
}

Builder::~Builder() {
  Cleanup();
  status_->SetExplanations(nullptr);
}

void Builder::Cleanup() {
  if (command_runner_.get()) {
    std::vector<Edge*> active_edges = command_runner_->GetActiveEdges();
    command_runner_->Abort();

    for (Edge* e : active_edges) {
      std::string depfile = e->GetUnescapedDepfile();
      for (Node* o : e->outputs_) {
        // Only delete outputs that were actually modified (or always when a
        // depfile is used, since the depfile may already be updated).
        std::string err;
        TimeStamp new_mtime = disk_interface_->Stat(o->path(), &err);
        if (new_mtime == -1)  // Log and ignore Stat() errors.
          status_->Error("%s", err.c_str());
        if (!depfile.empty() || o->mtime() != new_mtime)
          disk_interface_->RemoveFile(o->path());
      }
      if (!depfile.empty())
        disk_interface_->RemoveFile(depfile);
    }
  }

  std::string err;
  if (disk_interface_->Stat(lock_file_path_, &err) > 0)
    disk_interface_->RemoveFile(lock_file_path_);
}

Node* Builder::AddTarget(const std::string& name, std::string* err) {
  Node* node = state_->LookupNode(name);
  if (!node) {
    *err = "unknown target: '" + name + "'";
    return nullptr;
  }
  if (!AddTarget(node, err))
    return nullptr;
  return node;
}

bool Builder::AddTarget(Node* target, std::string* err) {
  std::vector<Node*> validation_nodes;
  if (!scan_.RecomputeDirty(target, &validation_nodes, err))
    return false;

  Edge* in_edge = target->in_edge();
  if (!in_edge || !in_edge->outputs_ready()) {
    if (!plan_.AddTarget(target, err))
      return false;
  }

  // Validation nodes become top level targets too.
  for (Node* n : validation_nodes) {
    if (Edge* validation_in_edge = n->in_edge()) {
      if (!validation_in_edge->outputs_ready() && !plan_.AddTarget(n, err))
        return false;
    }
  }

  return true;
}

bool Builder::AlreadyUpToDate() const { return !plan_.more_to_do(); }

ExitStatus Builder::Build(std::string* err) {
  assert(!AlreadyUpToDate());
  plan_.PrepareQueue();

  int pending_commands = 0;
  int failures_allowed = config_.failures_allowed;

  if (!command_runner_.get()) {
    if (config_.dry_run)
      command_runner_.reset(new DryRunCommandRunner);
    else
      command_runner_.reset(CommandRunner::factory(config_, jobserver_));
  }

  status_->BuildStarted();

  // Start as many commands as allowed, then wait for one to finish.
  while (plan_.more_to_do()) {
    if (failures_allowed) {
      size_t capacity = command_runner_->CanRunMore();
      while (capacity > 0) {
        Edge* edge = plan_.FindWork();
        if (!edge)
          break;

        if (edge->GetBindingBool("generator")) {
          scan_.build_log()->Close();
        }

        if (!StartEdge(edge, err)) {
          Cleanup();
          status_->BuildFinished();
          return ExitFailure;
        }

        if (edge->is_phony()) {
          if (!plan_.EdgeFinished(edge, Plan::kEdgeSucceeded, err)) {
            Cleanup();
            status_->BuildFinished();
            return ExitFailure;
          }
        } else {
          ++pending_commands;

          --capacity;

          size_t current_capacity = command_runner_->CanRunMore();
          if (current_capacity < capacity)
            capacity = current_capacity;
        }
      }

      if (pending_commands == 0 && !plan_.more_to_do())
        break;
    }

    if (pending_commands) {
      CommandRunner::Result result;
      if (!command_runner_->WaitForCommand(&result) ||
          result.status == ExitInterrupted) {
        Cleanup();
        status_->BuildFinished();
        *err = "interrupted by user";
        return ExitInterrupted;
      }

      --pending_commands;
      bool command_finished = FinishCommand(&result, err);
      if (!result.success())
        exit_code_ = result.status;
      if (!command_finished) {
        Cleanup();
        status_->BuildFinished();
        return result.success() ? ExitFailure : result.status;
      }

      if (!result.success()) {
        if (failures_allowed)
          failures_allowed--;
      }

      continue;
    }

    // Can't make any more progress.
    status_->BuildFinished();
    if (failures_allowed == 0) {
      if (config_.failures_allowed > 1)
        *err = "subcommands failed";
      else
        *err = "subcommand failed";
    } else if (failures_allowed < config_.failures_allowed) {
      *err = "cannot make progress due to previous errors";
    } else {
      *err = "stuck [this is a bug]";
    }

    return exit_code_ != ExitSuccess ? exit_code_ : ExitFailure;
  }

  status_->BuildFinished();
  return ExitSuccess;
}

bool Builder::StartEdge(Edge* edge, std::string* err) {
  METRIC_RECORD("StartEdge");
  if (edge->is_phony())
    return true;

  int64_t start_time_millis = GetTimeMillis() - start_time_millis_;
  running_edges_.insert(std::make_pair(edge, start_time_millis));

  status_->BuildEdgeStarted(edge, start_time_millis);

  TimeStamp build_start = config_.dry_run ? 0 : -1;

  // Create output directories and note the current filesystem time, which
  // is recorded in the log later.
  for (Node* o : edge->outputs_) {
    if (!disk_interface_->MakeDirs(o->path()))
      return false;
    if (build_start == -1) {
      disk_interface_->WriteFile(lock_file_path_, "");
      build_start = disk_interface_->Stat(lock_file_path_, err);
      if (build_start == -1)
        build_start = 0;
    }
  }

  edge->command_start_time_ = build_start;

  // Create the depfile directory if needed.
  std::string depfile = edge->GetUnescapedDepfile();
  if (!depfile.empty() && !disk_interface_->MakeDirs(depfile))
    return false;

  // Write the response file, if any.
  std::string rspfile = edge->GetUnescapedRspfile();
  if (!rspfile.empty()) {
    std::string content = edge->GetBinding("rspfile_content");
    if (!disk_interface_->WriteFile(rspfile, content))
      return false;
  }

  if (!command_runner_->StartCommand(edge)) {
    err->assign("command '" + edge->EvaluateCommand() + "' failed.");
    return false;
  }

  return true;
}

bool Builder::FinishCommand(CommandRunner::Result* result, std::string* err) {
  METRIC_RECORD("FinishCommand");

  Edge* edge = result->edge;

  // Extract dependencies first: this filters the command output (even on
  // failure) and can itself fail.
  std::vector<Node*> deps_nodes;
  std::string deps_type = edge->GetBinding("deps");
  const std::string deps_prefix = edge->GetBinding("msvc_deps_prefix");
  if (!deps_type.empty()) {
    std::string extract_err;
    if (!ExtractDeps(result, deps_type, deps_prefix, &deps_nodes,
                     &extract_err) &&
        result->success()) {
      if (!result->output.empty())
        result->output.append("\n");
      result->output.append(extract_err);
      result->status = ExitFailure;
    }
  }

  int64_t start_time_millis, end_time_millis;
  auto it = running_edges_.find(edge);
  start_time_millis = it->second;
  end_time_millis = GetTimeMillis() - start_time_millis_;
  running_edges_.erase(it);

  status_->BuildEdgeFinished(edge, start_time_millis, end_time_millis,
                             result->status, result->output);

  if (!result->success())
    return plan_.EdgeFinished(edge, Plan::kEdgeFailed, err);

  // Restat the outputs.
  TimeStamp record_mtime = 0;
  if (!config_.dry_run) {
    const bool restat = edge->GetBindingBool("restat");
    const bool generator = edge->GetBindingBool("generator");
    bool node_cleaned = false;
    record_mtime = edge->command_start_time_;

    // restat and generator rules must restat outputs after the build; so do
    // we if the lock file couldn't be stat'ed at edge start.
    if (record_mtime == 0 || restat || generator) {
      for (Node* o : edge->outputs_) {
        TimeStamp new_mtime = disk_interface_->Stat(o->path(), err);
        if (new_mtime == -1)
          return false;
        if (new_mtime > record_mtime)
          record_mtime = new_mtime;
        if (o->mtime() == new_mtime && restat) {
          // The command didn't change this output: propagate clean state.
          if (!plan_.CleanNode(&scan_, o, err))
            return false;
          node_cleaned = true;
        }
      }
    }
    if (node_cleaned)
      record_mtime = edge->command_start_time_;
  }

  if (!plan_.EdgeFinished(edge, Plan::kEdgeSucceeded, err))
    return false;

  // Delete any left over response file.
  std::string rspfile = edge->GetUnescapedRspfile();
  if (!rspfile.empty() && !g_keep_rsp)
    disk_interface_->RemoveFile(rspfile);

  if (scan_.build_log()) {
    if (!scan_.build_log()->RecordCommand(edge, start_time_millis,
                                          end_time_millis, record_mtime)) {
      *err = std::string("Error writing to build log: ") + strerror(errno);
      return false;
    }
  }

  if (!deps_type.empty() && !config_.dry_run) {
    assert(!edge->outputs_.empty());
    for (Node* o : edge->outputs_) {
      TimeStamp deps_mtime = disk_interface_->Stat(o->path(), err);
      if (deps_mtime == -1)
        return false;
      if (!scan_.deps_log()->RecordDeps(o, deps_mtime, deps_nodes)) {
        *err = std::string("Error writing to deps log: ") + strerror(errno);
        return false;
      }
    }
  }
  return true;
}

bool Builder::ExtractDeps(CommandRunner::Result* result,
                          const std::string& deps_type,
                          const std::string& deps_prefix,
                          std::vector<Node*>* deps_nodes, std::string* err) {
  if (deps_type == "msvc") {
    CLParser parser;
    std::string output;
    if (!parser.Parse(result->output, deps_prefix, &output, err))
      return false;
    result->output = output;
    for (const std::string& inc : parser.includes_)
      deps_nodes->push_back(state_->GetNode(inc, ~0u));
  } else if (deps_type == "gcc") {
    std::string depfile = result->edge->GetUnescapedDepfile();
    if (depfile.empty()) {
      *err = std::string("edge with deps=gcc but no depfile makes no sense");
      return false;
    }

    // Read depfile content.  Treat a missing depfile as empty.
    std::string content;
    switch (disk_interface_->ReadFile(depfile, &content, err)) {
      case DiskInterface::Okay:
        break;
      case DiskInterface::NotFound:
        err->clear();
        break;
      case DiskInterface::OtherError:
        return false;
    }
    if (content.empty())
      return true;

    DepfileParser deps;
    if (!deps.Parse(&content, err))
      return false;

    deps_nodes->reserve(deps.ins_.size());
    for (std::string& in : deps.ins_) {
      uint64_t slash_bits;
      CanonicalizePath(&in, &slash_bits);
      deps_nodes->push_back(state_->GetNode(in, slash_bits));
    }

    if (!g_keep_depfile) {
      if (disk_interface_->RemoveFile(depfile) < 0) {
        *err = std::string("deleting depfile: ") + strerror(errno) +
               std::string("\n");
        return false;
      }
    }
  } else {
    Fatal("unknown deps type '%s'", deps_type.c_str());
  }

  return true;
}

bool Builder::LoadDyndeps(Node* node, std::string* err) {
  DyndepFile ddf;
  if (!scan_.LoadDyndeps(node, &ddf, err))
    return false;

  if (!plan_.DyndepsLoaded(&scan_, node, ddf, err))
    return false;

  return true;
}
