  PrintFooter();
  return status_;
}

void Cleaner::DoCleanTarget(Node* target) {
  if (Edge* e = target->in_edge()) {
    // Phony targets have nothing to remove.
    if (!e->is_phony()) {
      Remove(target->path());
      RemoveEdgeFiles(e);
    }
    for (Node* next : e->inputs_) {
      if (cleaned_.count(next) == 0)
        DoCleanTarget(next);
