cat > browse.cc <<'EOF'
#include "browse.h"

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#include <vector>

#include "browse_py.h"

#define NINJA_PYTHON "python"

void RunBrowsePython(State*, const char* ninja_command, const char* input_file,
                     int argc, char* argv[]) {
  // The Python interpreter becomes the parent process and reads the script
  // from its stdin, which a forked child writes.
  int pipefd[2];
  if (pipe(pipefd) < 0) {
    perror("ninja: pipe");
    return;
  }

  pid_t pid = fork();
  if (pid < 0) {
    perror("ninja: fork");
    return;
  }

  if (pid > 0) {  // Parent.
    close(pipefd[1]);
    do {
      if (dup2(pipefd[0], 0) < 0) {
        perror("ninja: dup2");
        break;
      }

      std::vector<const char*> command;
      command.push_back(NINJA_PYTHON);
      command.push_back("-");
      command.push_back("--ninja-command");
      command.push_back(ninja_command);
      command.push_back("-f");
      command.push_back(input_file);
      for (int i = 0; i < argc; i++)
        command.push_back(argv[i]);
      command.push_back(nullptr);
      execvp(command[0], (char**)&command[0]);
      if (errno == ENOENT) {
        printf("ninja: %s is required for the browse tool\n", NINJA_PYTHON);
      } else {
        perror("ninja: execvp");
      }
    } while (false);
    _exit(1);
  } else {  // Child.
    close(pipefd[0]);

    // Don't write the terminating NUL; Python rejects it in source.
    size_t len = sizeof(kBrowsePy) - 1;
    ssize_t written = write(pipefd[1], kBrowsePy, len);
    if (written < (ssize_t)len)
      perror("ninja: write");
    close(pipefd[1]);
    exit(0);
  }
}
