// Command line driver: flag parsing, manifest loading and the subtools.
#include <errno.h>
#include <getopt.h>
#include <inttypes.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <algorithm>
#include <memory>
#include <string>
#include <vector>

#include "browse.h"
#include "build.h"
#include "build_log.h"
#include "clean.h"
#include "debug_flags.h"
#include "deps_log.h"
#include "disk_interface.h"
#include "graph.h"
#include "graphviz.h"
#include "jobserver.h"
#include "manifest_parser.h"
#include "metrics.h"
#include "missing_deps.h"
#include "status.h"
#include "urtle.h"
#include "util.h"

namespace {

struct Tool;

/// Command-line options.
struct Options {
  const char* input_file = nullptr;
  const char* working_dir = nullptr;
  const Tool* tool = nullptr;
  bool phony_cycle_should_err = false;
};

/// The state used for the whole run: loaded manifest, logs, etc.
struct NinjaMain : public BuildLogUser {
  NinjaMain(const char* ninja_command, const BuildConfig& config)
      : ninja_command_(ninja_command),
        config_(config),
        start_time_millis_(GetTimeMillis()) {}

  const char* ninja_command_;
  const BuildConfig& config_;
  State state_;
  RealDiskInterface disk_interface_;
  std::string build_dir_;
  BuildLog build_log_;
  DepsLog deps_log_;

  typedef int (NinjaMain::*ToolFunc)(const Options*, int, char**);

  std::string EnsureNonEmpty(const std::string& s) { return s; }

  Node* CollectTarget(const char* cpath, std::string* err);
  bool CollectTargetsFromArgs(int argc, char* argv[],
                              std::vector<Node*>* targets, std::string* err);

  int ToolGraph(const Options* options, int argc, char* argv[]);
  int ToolQuery(const Options* options, int argc, char* argv[]);
  int ToolDeps(const Options* options, int argc, char* argv[]);
  int ToolMissingDeps(const Options* options, int argc, char* argv[]);
  int ToolBrowse(const Options* options, int argc, char* argv[]);
  int ToolTargets(const Options* options, int argc, char* argv[]);
  int ToolCommands(const Options* options, int argc, char* argv[]);
  int ToolInputs(const Options* options, int argc, char* argv[]);
  int ToolMultiInputs(const Options* options, int argc, char* argv[]);
  int ToolClean(const Options* options, int argc, char* argv[]);
  int ToolCleanDead(const Options* options, int argc, char* argv[]);
  int ToolCompilationDatabase(const Options* options, int argc, char* argv[]);
  int ToolCompilationDatabaseForTargets(const Options* options, int argc,
                                        char* argv[]);
  int ToolRecompact(const Options* options, int argc, char* argv[]);
  int ToolRestat(const Options* options, int argc, char* argv[]);
  int ToolUrtle(const Options* options, int argc, char** argv);
  int ToolRules(const Options* options, int argc, char* argv[]);

  bool OpenBuildLog(bool recompact_only = false);
  bool OpenDepsLog(bool recompact_only = false);
  bool EnsureBuildDirExists();
  bool RebuildManifest(const char* input_file, std::string* err,
                       Status* status);
  void ParsePreviousElapsedTimes();
  ExitStatus RunBuild(int argc, char** argv, Status* status);
  void DumpMetrics();

  bool IsPathDead(std::string_view s) const override {
    Node* n = state_.LookupNode(s);
    if (n && n->in_edge())
      return false;
    // Keep entries for files that still exist on disk; generators may
    // want that information.
    std::string err;
    TimeStamp mtime = disk_interface_.Stat(std::string(s), &err);
    if (mtime == -1)
      Error("%s", err.c_str());  // Log and ignore Stat() errors.
    return mtime == 0;
  }

  int64_t start_time_millis_;
};

/// Subtools, accessible via "-t foo".
struct Tool {
  const char* name;
  const char* desc;

  enum {
    RUN_AFTER_FLAGS,  // run before parsing the manifest
    RUN_AFTER_LOAD,   // run after loading the manifest
    RUN_AFTER_LOGS,   // run after loading the build and deps logs
  } when;

  NinjaMain::ToolFunc func;
};

void Usage(const BuildConfig& config) {
  fprintf(stderr,
          "usage: ninja [options] [targets...]\n"
          "\n"
          "if targets are unspecified, builds the 'default' target (see "
          "manual).\n"
          "\n"
          "options:\n"
          "  --version      print ninja version (\"%s\")\n"
          "  -v, --verbose  show all command lines while building\n"
          "  --quiet        don't show progress status, just command output\n"
          "\n"
          "  -C DIR   change to DIR before doing anything else\n"
          "  -f FILE  specify input build file [default=build.ninja]\n"
          "\n"
          "  -j N     run N jobs in parallel (0 means infinity) [default=%d on "
          "this system]\n"
          "  -k N     keep going until N jobs fail (0 means infinity) "
          "[default=1]\n"
          "  -l N     do not start new jobs if the load average is greater "
          "than N\n"
          "  -n       dry run (don't run commands but act like they "
          "succeeded)\n"
          "\n"
          "  -d MODE  enable debugging (use '-d list' to list modes)\n"
          "  -t TOOL  run a subtool (use '-t list' to list subtools)\n"
          "    terminates toplevel options; further flags are passed to the "
          "tool\n"
          "  -w FLAG  adjust warnings (use '-w list' to list warnings)\n",
          kNinjaVersion, config.parallelism);
}

int GuessParallelism() {
  switch (int processors = GetProcessorCount()) {
    case 0:
    case 1:
      return 2;
    case 2:
      return 3;
    default:
      return processors + 2;
  }
}

bool NinjaMain::RebuildManifest(const char* input_file, std::string* err,
                                Status* status) {
  std::string path = input_file;
  if (path.empty()) {
    *err = "empty path";
    return false;
  }
  uint64_t slash_bits;  // Unused: path is only used for lookup.
  CanonicalizePath(&path, &slash_bits);
  Node* node = state_.LookupNode(path);
  if (!node)
    return false;

  Builder builder(&state_, config_, &build_log_, &deps_log_, &disk_interface_,
                  status, start_time_millis_);
  if (!builder.AddTarget(node, err))
    return false;

  if (builder.AlreadyUpToDate())
    return false;  // Not an error, but we didn't rebuild.

  if (builder.Build(err) != ExitSuccess)
    return false;

  // The manifest was only rebuilt if it is now dirty (a restat may have
  // cleaned it).
  if (!node->dirty()) {
    state_.Reset();
    return false;
  }

  return true;
}

void NinjaMain::ParsePreviousElapsedTimes() {
  for (Edge* edge : state_.edges_) {
    for (Node* out : edge->outputs_) {
      BuildLog::LogEntry* log_entry = build_log_.LookupByOutput(out->path());
      if (!log_entry)
        continue;
      edge->prev_elapsed_time_millis =
          log_entry->end_time - log_entry->start_time;
      break;
    }
  }
}

Node* NinjaMain::CollectTarget(const char* cpath, std::string* err) {
  std::string path = cpath;
  if (path.empty()) {
    *err = "empty path";
    return nullptr;
  }
  uint64_t slash_bits;
  CanonicalizePath(&path, &slash_bits);

  // "foo.cc^" means "the first output of foo.cc".
  bool first_dependent = false;
  if (!path.empty() && path[path.size() - 1] == '^') {
    path.resize(path.size() - 1);
    first_dependent = true;
  }

  Node* node = state_.LookupNode(path);
  if (node) {
    if (first_dependent) {
      if (node->out_edges().empty()) {
        Node* rev_deps = deps_log_.GetFirstReverseDepsNode(node);
        if (!rev_deps) {
          *err = "'" + path + "' has no out edge";
          return nullptr;
        }
        node = rev_deps;
      } else {
        Edge* edge = node->out_edges()[0];
        if (edge->outputs_.empty()) {
          edge->Dump();
          Fatal("edge has no outputs");
        }
        node = edge->outputs_[0];
      }
    }
    return node;
  } else {
    *err = "unknown target '" + path + "'";
    if (path == "clean") {
      *err += ", did you mean 'ninja -t clean'?";
    } else if (path == "help") {
      *err += ", did you mean 'ninja -h'?";
    } else {
      Node* suggestion = state_.SpellcheckNode(path);
      if (suggestion)
        *err += ", did you mean '" + suggestion->path() + "'?";
    }
    return nullptr;
  }
}

bool NinjaMain::CollectTargetsFromArgs(int argc, char* argv[],
                                       std::vector<Node*>* targets,
                                       std::string* err) {
  if (argc == 0) {
    *targets = state_.DefaultNodes(err);
    return err->empty();
  }

  for (int i = 0; i < argc; ++i) {
    Node* node = CollectTarget(argv[i], err);
    if (node == nullptr)
      return false;
    targets->push_back(node);
  }
  return true;
}

int NinjaMain::ToolGraph(const Options*, int argc, char* argv[]) {
  std::vector<Node*> nodes;
  std::string err;
  if (!CollectTargetsFromArgs(argc, argv, &nodes, &err)) {
    Error("%s", err.c_str());
    return 1;
  }

  GraphViz graph(&state_, &disk_interface_);
  graph.Start();
  for (Node* n : nodes)
    graph.AddTarget(n);
  graph.Finish();

  return 0;
}

int NinjaMain::ToolQuery(const Options*, int argc, char* argv[]) {
  if (argc == 0) {
    Error("expected a target to query");
    return 1;
  }

  DyndepLoader dyndep_loader(&state_, &disk_interface_);

  for (int i = 0; i < argc; ++i) {
    std::string err;
    Node* node = CollectTarget(argv[i], &err);
    if (!node) {
      Error("%s", err.c_str());
      return 1;
    }

    printf("%s:\n", node->path().c_str());
    if (Edge* edge = node->in_edge()) {
      if (edge->dyndep_ && edge->dyndep_->dyndep_pending()) {
        if (!dyndep_loader.LoadDyndeps(edge->dyndep_, &err))
          Warning("%s\n", err.c_str());
      }
      printf("  input: %s\n", edge->rule_->name().c_str());
      for (int in = 0; in < (int)edge->inputs_.size(); in++) {
        const char* label = "";
        if (edge->is_implicit(in))
          label = "| ";
        else if (edge->is_order_only(in))
          label = "|| ";
        printf("    %s%s\n", label, edge->inputs_[in]->path().c_str());
      }
      if (!edge->validations_.empty()) {
        printf("  validations:\n");
        for (Node* v : edge->validations_)
          printf("    %s\n", v->path().c_str());
      }
    }
    printf("  outputs:\n");
    for (Edge* edge : node->out_edges()) {
      for (Node* out : edge->outputs_)
        printf("    %s\n", out->path().c_str());
    }
    const std::vector<Edge*>& validation_edges = node->validation_out_edges();
    if (!validation_edges.empty()) {
      printf("  validation for:\n");
      for (Edge* edge : validation_edges) {
        for (Node* out : edge->outputs_)
          printf("    %s\n", out->path().c_str());
      }
    }
  }
  return 0;
}

int NinjaMain::ToolBrowse(const Options* options, int argc, char* argv[]) {
  RunBrowsePython(&state_, ninja_command_, options->input_file, argc, argv);
  // If we get here, the browse failed.
  return 1;
}

int NinjaMain::ToolDeps(const Options*, int argc, char** argv) {
  std::vector<Node*> nodes;
  if (argc == 0) {
    for (Node* n : deps_log_.nodes()) {
      if (DepsLog::IsDepsEntryLiveFor(n))
        nodes.push_back(n);
    }
  } else {
    std::string err;
    if (!CollectTargetsFromArgs(argc, argv, &nodes, &err)) {
      Error("%s", err.c_str());
      return 1;
    }
  }

  RealDiskInterface disk_interface;
  for (Node* n : nodes) {
    DepsLog::Deps* deps = deps_log_.GetDeps(n);
    if (!deps) {
      printf("%s: deps not found\n", n->path().c_str());
      continue;
    }

    std::string err;
    TimeStamp mtime = disk_interface.Stat(n->path(), &err);
    if (mtime == -1)
      Error("%s", err.c_str());  // Log and ignore Stat() errors;
    printf("%s: #deps %d, deps mtime %" PRId64 " (%s)\n", n->path().c_str(),
           deps->node_count, deps->mtime,
           (!mtime || mtime > deps->mtime ? "STALE" : "VALID"));
    for (int i = 0; i < deps->node_count; ++i)
      printf("    %s\n", deps->nodes[i]->path().c_str());
    printf("\n");
  }

  return 0;
}

int NinjaMain::ToolMissingDeps(const Options*, int argc, char** argv) {
  std::vector<Node*> nodes;
  std::string err;
  if (!CollectTargetsFromArgs(argc, argv, &nodes, &err)) {
    Error("%s", err.c_str());
    return 1;
  }
  RealDiskInterface disk_interface;
  MissingDependencyPrinter printer;
  MissingDependencyScanner scanner(&printer, &deps_log_, &state_,
                                   &disk_interface);
  for (Node* n : nodes)
    scanner.ProcessNode(n);
  scanner.PrintStats();
  if (scanner.HadMissingDeps())
    return 3;
  return 0;
}

int ToolTargetsList(const std::vector<Node*>& nodes, int depth, int indent) {
  for (Node* n : nodes) {
    for (int i = 0; i < indent; ++i)
      printf("  ");
    const char* target = n->path().c_str();
    if (n->in_edge()) {
      printf("%s: %s\n", target, n->in_edge()->rule_->name().c_str());
      if (depth > 1 || depth <= 0)
        ToolTargetsList(n->in_edge()->inputs_, depth - 1, indent + 1);
    } else {
      printf("%s\n", target);
    }
  }
  return 0;
}

int ToolTargetsSourceList(State* state) {
  for (Edge* e : state->edges_) {
    for (Node* inps : e->inputs_) {
      if (!inps->in_edge())
        printf("%s\n", inps->path().c_str());
    }
  }
  return 0;
}

int ToolTargetsList(State* state, const std::string& rule_name) {
  std::set<std::string> rules;

  for (Edge* e : state->edges_) {
    if (e->rule_->name() == rule_name) {
      for (Node* out_node : e->outputs_)
        rules.insert(out_node->path());
    }
  }

  for (const std::string& r : rules)
    printf("%s\n", r.c_str());

  return 0;
}

int ToolTargetsList(State* state) {
  for (Edge* e : state->edges_) {
    for (Node* out_node : e->outputs_) {
      printf("%s: %s\n", out_node->path().c_str(), e->rule_->name().c_str());
    }
  }
  return 0;
}

int NinjaMain::ToolTargets(const Options*, int argc, char* argv[]) {
  int depth = 1;
  if (argc >= 1) {
    std::string mode = argv[0];
    if (mode == "rule") {
      std::string rule;
      if (argc > 1)
        rule = argv[1];
      if (rule.empty())
        return ToolTargetsSourceList(&state_);
      else
        return ToolTargetsList(&state_, rule);
    } else if (mode == "depth") {
      if (argc > 1)
        depth = atoi(argv[1]);
    } else if (mode == "all") {
      return ToolTargetsList(&state_);
    } else {
      const char* suggestion =
          SpellcheckString(mode.c_str(), "rule", "depth", "all", nullptr);
      if (suggestion) {
        Error("unknown target tool mode '%s', did you mean '%s'?",
              mode.c_str(), suggestion);
      } else {
        Error("unknown target tool mode '%s'", mode.c_str());
      }
      return 1;
    }
  }

  std::string err;
  std::vector<Node*> root_nodes = state_.RootNodes(&err);
  if (err.empty()) {
    return ToolTargetsList(root_nodes, depth, 0);
  } else {
    Error("%s", err.c_str());
    return 1;
  }
}

int NinjaMain::ToolRules(const Options*, int argc, char* argv[]) {
  // The rules tool uses getopt and expects argv[0] to be the tool name.
  argc++;
  argv--;

  bool print_description = false;

  optind = 1;
  int opt;
  while ((opt = getopt(argc, argv, const_cast<char*>("hd"))) != -1) {
    switch (opt) {
      case 'd':
        print_description = true;
        break;
      case 'h':
      default:
        printf(
            "usage: ninja -t rules [options]\n"
            "\n"
            "options:\n"
            "  -d     also print the description of the rule\n"
            "  -h     print this message\n");
        return 1;
    }
  }
  argv += optind;
  argc -= optind;

  for (auto& r : state_.bindings_.GetRules()) {
    printf("%s", r.first.c_str());
    if (print_description) {
      const Rule* rule = r.second.get();
      const EvalString* description = rule->GetBinding("description");
      if (description != nullptr)
        printf(": %s", description->Unparse().c_str());
    }
    printf("\n");
    fflush(stdout);
  }
  return 0;
}

enum PrintCommandMode { PCM_Single, PCM_All };
void PrintCommands(Edge* edge, EdgeSet* seen, PrintCommandMode mode) {
  if (!edge)
    return;
  if (!seen->insert(edge).second)
    return;

  if (mode == PCM_All) {
    for (Node* in : edge->inputs_)
      PrintCommands(in->in_edge(), seen, mode);
  }

  if (!edge->is_phony())
    puts(edge->EvaluateCommand().c_str());
}

int NinjaMain::ToolCommands(const Options*, int argc, char* argv[]) {
  ++argc;
  --argv;

  PrintCommandMode mode = PCM_All;

  optind = 1;
  int opt;
  while ((opt = getopt(argc, argv, const_cast<char*>("hs"))) != -1) {
    switch (opt) {
      case 's':
        mode = PCM_Single;
        break;
      case 'h':
      default:
        printf(
            "usage: ninja -t commands [options] [targets]\n"
            "\n"
            "options:\n"
            "  -s     only print the final command to build [target], not the "
            "whole chain\n");
        return 1;
    }
  }
  argv += optind;
  argc -= optind;

  std::vector<Node*> nodes;
  std::string err;
  if (!CollectTargetsFromArgs(argc, argv, &nodes, &err)) {
    Error("%s", err.c_str());
    return 1;
  }

  EdgeSet seen;
  for (Node* n : nodes)
    PrintCommands(n->in_edge(), &seen, mode);

  return 0;
}

int NinjaMain::ToolInputs(const Options*, int argc, char* argv[]) {
  argc++;
  argv--;

  bool print0 = false;
  bool shell_escape = true;
  bool dependency_order = false;

  optind = 1;
  int opt;
  const option kLongOptions[] = {{"help", no_argument, nullptr, 'h'},
                                 {"no-shell-escape", no_argument, nullptr, 'E'},
                                 {"print0", no_argument, nullptr, '0'},
                                 {"dependency-order", no_argument, nullptr,
                                  'd'},
                                 {nullptr, 0, nullptr, 0}};
  while ((opt = getopt_long(argc, argv, "h0Ed", kLongOptions, nullptr)) !=
         -1) {
    switch (opt) {
      case 'd':
        dependency_order = true;
        break;
      case 'E':
        shell_escape = false;
        break;
      case '0':
        print0 = true;
        break;
      case 'h':
      default:
        printf(
            "Usage '-t inputs [options] [targets]\n"
            "\n"
            "List all inputs used for a set of targets, sorted in dependency "
            "order.\n"
            "Note that by default, results are shell escaped, and sorted "
            "alphabetically,\n"
            "and never include validation target paths.\n"
            "\n"
            "Options:\n"
            "  -h, --help          Print this message.\n"
            "  -0, --print0            Use \\0, instead of \\n as a line "
            "terminator.\n"
            "  -E, --no-shell-escape   Do not shell escape the result.\n"
            "  -d, --dependency-order  Sort results by dependency order.\n");
        return 1;
    }
  }
  argv += optind;
  argc -= optind;

  std::vector<Node*> nodes;
  std::string err;
  if (!CollectTargetsFromArgs(argc, argv, &nodes, &err)) {
    Error("%s", err.c_str());
    return 1;
  }

  InputsCollector collector;
  for (const Node* node : nodes)
    collector.VisitNode(node);

  std::vector<std::string> inputs = collector.GetInputsAsStrings(shell_escape);
  if (!dependency_order)
    std::sort(inputs.begin(), inputs.end());

  if (print0) {
    for (const std::string& input : inputs) {
      fwrite(input.c_str(), input.size(), 1, stdout);
      fputc('\0', stdout);
    }
    fflush(stdout);
  } else {
    for (const std::string& input : inputs)
      puts(input.c_str());
  }
  return 0;
}

int NinjaMain::ToolMultiInputs(const Options*, int argc, char* argv[]) {
  argc++;
  argv--;

  optind = 1;
  int opt;
  char terminator = '\n';
  const char* delimiter = "\t";
  const option kLongOptions[] = {{"help", no_argument, nullptr, 'h'},
                                 {"delimiter", required_argument, nullptr, 'd'},
                                 {"print0", no_argument, nullptr, '0'},
                                 {nullptr, 0, nullptr, 0}};
  while ((opt = getopt_long(argc, argv, "d:h0", kLongOptions, nullptr)) !=
         -1) {
    switch (opt) {
      case 'd':
        delimiter = optarg;
        break;
      case '0':
        terminator = '\0';
        break;
      case 'h':
      default:
        printf(
            "Usage '-t multi-inputs [options] [targets]\n"
            "\n"
            "Print one or more sets of inputs required to build targets, "
            "sorted in dependency order.\n"
            "The tool works like inputs tool but with addition of the target "
            "for each line.\n"
            "The output will be a series of lines with the following "
            "elements:\n"
            "<target> <delimiter> <input> <terminator>\n"
            "Note that a given input may appear for several targets if it is "
            "used by more than one targets.\n"
            "Options:\n"
            "  -h, --help                   Print this message.\n"
            "  -d  --delimiter=DELIM        Use DELIM instead of TAB for field "
            "delimiter.\n"
            "  -0, --print0                 Use \\0, instead of \\n as a line "
            "terminator.\n");
        return 1;
    }
  }
  argv += optind;
  argc -= optind;

  std::vector<Node*> nodes;
  std::string err;
  if (!CollectTargetsFromArgs(argc, argv, &nodes, &err)) {
    Error("%s", err.c_str());
    return 1;
  }

  for (const Node* node : nodes) {
    InputsCollector collector;

    collector.VisitNode(node);
    std::vector<std::string> inputs = collector.GetInputsAsStrings();

    for (const std::string& input : inputs) {
      printf("%s%s%s", node->path().c_str(), delimiter, input.c_str());
      fputc(terminator, stdout);
    }
  }

  return 0;
}

int NinjaMain::ToolClean(const Options*, int argc, char* argv[]) {
  argc++;
  argv--;

  bool generator = false;
  bool clean_rules = false;

  optind = 1;
  int opt;
  while ((opt = getopt(argc, argv, const_cast<char*>("hgr"))) != -1) {
    switch (opt) {
      case 'g':
        generator = true;
        break;
      case 'r':
        clean_rules = true;
        break;
      case 'h':
      default:
        printf(
            "usage: ninja -t clean [options] [targets]\n"
            "\n"
            "options:\n"
            "  -g     also clean files marked as ninja generator output\n"
            "  -r     interpret targets as a list of rules to clean instead\n");
        return 1;
    }
  }
  argv += optind;
  argc -= optind;

  if (clean_rules && argc == 0) {
    Error("expected a rule to clean");
    return 1;
  }

  Cleaner cleaner(&state_, config_, &disk_interface_);
  if (argc >= 1) {
    if (clean_rules)
      return cleaner.CleanRules(argc, argv);
    else
      return cleaner.CleanTargets(argc, argv);
  } else {
    return cleaner.CleanAll(generator);
  }
}

int NinjaMain::ToolCleanDead(const Options*, int, char*[]) {
  Cleaner cleaner(&state_, config_, &disk_interface_);
  return cleaner.CleanDead(build_log_.entries());
}

enum EvaluateCommandMode { ECM_NORMAL, ECM_EXPAND_RSPFILE };

std::string EvaluateCommandWithRspfile(const Edge* edge,
                                       const EvaluateCommandMode mode) {
  std::string command = edge->EvaluateCommand();
  if (mode == ECM_NORMAL)
    return command;

  std::string rspfile = edge->GetUnescapedRspfile();
  if (rspfile.empty())
    return command;

  size_t index = command.find(rspfile);
  if (index == 0 || index == std::string::npos)
    return command;

  size_t replace_start, replace_len;
  if (command[index - 1] == '@') {
    replace_start = index - 1;
    replace_len = rspfile.length() + 1;
  } else if (index >= 14 &&
             command.compare(index - 14, 14, "--option-file=") == 0) {
    replace_start = index - 14;
    replace_len = rspfile.length() + 14;
  } else {
    return command;
  }

  std::string rspfile_content = edge->GetBinding("rspfile_content");
  size_t newline_index = 0;
  while ((newline_index = rspfile_content.find('\n', newline_index)) !=
         std::string::npos) {
    rspfile_content.replace(newline_index, 1, 1, ' ');
    ++newline_index;
  }
  command.replace(replace_start, replace_len, rspfile_content);
  return command;
}

void PrintCompdb(const std::string& directory, const Edge* edge,
                 const EvaluateCommandMode eval_mode, bool* first) {
  std::string command = EvaluateCommandWithRspfile(edge, eval_mode);
  for (const Node* input : edge->inputs_) {
    if (!*first)
      putchar(',');
    *first = false;
    printf("\n  {\n    \"directory\": \"");
    PrintJSONString(directory);
    printf("\",\n    \"command\": \"");
    PrintJSONString(command);
    printf("\",\n    \"file\": \"");
    PrintJSONString(input->path());
    printf("\",\n    \"output\": \"");
    PrintJSONString(edge->outputs_[0]->path());
    printf("\"\n  }");
  }
}

int NinjaMain::ToolCompilationDatabase(const Options*, int argc,
                                       char* argv[]) {
  argc++;
  argv--;

  EvaluateCommandMode eval_mode = ECM_NORMAL;

  optind = 1;
  int opt;
  while ((opt = getopt(argc, argv, const_cast<char*>("hx"))) != -1) {
    switch (opt) {
      case 'x':
        eval_mode = ECM_EXPAND_RSPFILE;
        break;

      case 'h':
      default:
        printf(
            "usage: ninja -t compdb [options] [rules]\n"
            "\n"
            "options:\n"
            "  -x     expand @rspfile style response file invocations\n");
        return 1;
    }
  }
  argv += optind;
  argc -= optind;

  bool first = true;
  std::string cwd = GetWorkingDirectory();

  putchar('[');
  for (Edge* e : state_.edges_) {
    if (e->inputs_.empty())
      continue;
    if (argc == 0) {
      PrintCompdb(cwd, e, eval_mode, &first);
    } else {
      for (int i = 0; i != argc; ++i) {
        if (e->rule_->name() == argv[i])
          PrintCompdb(cwd, e, eval_mode, &first);
      }
    }
  }

  puts("\n]");
  return 0;
}

int NinjaMain::ToolCompilationDatabaseForTargets(const Options*, int argc,
                                                 char* argv[]) {
  argc++;
  argv--;

  EvaluateCommandMode eval_mode = ECM_NORMAL;

  optind = 1;
  int opt;
  const char* usage =
      "usage: ninja -t compdb [-hx] target [targets]\n"
      "\n"
      "options:\n"
      "  -h     display this help message\n"
      "  -x     expand @rspfile style response file invocations\n";
  while ((opt = getopt(argc, argv, const_cast<char*>("hx"))) != -1) {
    switch (opt) {
      case 'x':
        eval_mode = ECM_EXPAND_RSPFILE;
        break;
      case 'h':
      default:
        printf("%s", usage);
        return 1;
    }
  }
  argc -= optind;
  argv += optind;

  if (argc == 0) {
    Error("compdb-targets expects the name of at least one target");
    printf("%s", usage);
    return 1;
  }

  std::vector<Node*> targets;
  for (int i = 0; i < argc; ++i) {
    std::string err;
    Node* node = CollectTarget(argv[i], &err);
    if (!node) {
      Fatal("%s", err.c_str());
      return 1;
    }
    targets.push_back(node);
  }

  CommandCollector collector;
  for (const Node* node : targets)
    collector.CollectFrom(node);

  bool first = true;
  std::string cwd = GetWorkingDirectory();
  putchar('[');
  for (const Edge* edge : collector.in_edges)
    PrintCompdb(cwd, edge, eval_mode, &first);
  puts("\n]");
  return 0;
}

int NinjaMain::ToolRecompact(const Options*, int, char*[]) {
  if (!EnsureBuildDirExists())
    return 1;

  if (!OpenBuildLog(/*recompact_only=*/true) ||
      !OpenDepsLog(/*recompact_only=*/true))
    return 1;

  return 0;
}

int NinjaMain::ToolRestat(const Options*, int argc, char* argv[]) {
  argc++;
  argv--;

  optind = 1;
  int opt;
  while ((opt = getopt(argc, argv, const_cast<char*>("h"))) != -1) {
    switch (opt) {
      case 'h':
      default:
        printf("usage: ninja -t restat [outputs]\n");
        return 1;
    }
  }
  argv += optind;
  argc -= optind;

  if (!EnsureBuildDirExists())
    return 1;

  std::string log_path = ".ninja_log";
  if (!build_dir_.empty())
    log_path = build_dir_ + "/" + log_path;

  std::string err;
  const LoadStatus status = build_log_.Load(log_path, &err);
  if (status == LOAD_ERROR) {
    Error("loading build log %s: %s", log_path.c_str(), err.c_str());
    return EXIT_FAILURE;
  }
  if (status == LOAD_NOT_FOUND) {
    // Nothing to restat.
    return EXIT_SUCCESS;
  }
  if (!err.empty()) {
    // Load() can return a warning via err with LOAD_SUCCESS.
    Warning("%s", err.c_str());
    err.clear();
  }

  bool success = build_log_.Restat(log_path, disk_interface_, argc, argv, &err);
  if (!success) {
    Error("failed recompaction: %s", err.c_str());
    return EXIT_FAILURE;
  }

  if (!config_.dry_run) {
    if (!build_log_.OpenForWrite(log_path, *this, &err)) {
      Error("opening build log: %s", err.c_str());
      return EXIT_FAILURE;
    }
  }

  return EXIT_SUCCESS;
}

int NinjaMain::ToolUrtle(const Options*, int, char**) {
  fputs(kUrtle, stdout);
  return 0;
}

const Tool* ChooseTool(const std::string& tool_name) {
  static const Tool kTools[] = {
      {"browse", "browse dependency graph in a web browser",
       Tool::RUN_AFTER_LOAD, &NinjaMain::ToolBrowse},
      {"clean", "clean built files", Tool::RUN_AFTER_LOAD,
       &NinjaMain::ToolClean},
      {"commands", "list all commands required to rebuild given targets",
       Tool::RUN_AFTER_LOAD, &NinjaMain::ToolCommands},
      {"inputs", "list all inputs required to rebuild given targets",
       Tool::RUN_AFTER_LOAD, &NinjaMain::ToolInputs},
      {"multi-inputs",
       "print one or more sets of inputs required to build targets",
       Tool::RUN_AFTER_LOAD, &NinjaMain::ToolMultiInputs},
      {"deps", "show dependencies stored in the deps log",
       Tool::RUN_AFTER_LOGS, &NinjaMain::ToolDeps},
      {"missingdeps", "check deps log dependencies on generated files",
       Tool::RUN_AFTER_LOGS, &NinjaMain::ToolMissingDeps},
      {"graph", "output graphviz dot file for targets", Tool::RUN_AFTER_LOAD,
       &NinjaMain::ToolGraph},
      {"query", "show inputs/outputs for a path", Tool::RUN_AFTER_LOGS,
       &NinjaMain::ToolQuery},
      {"targets", "list targets by their rule or depth in the DAG",
       Tool::RUN_AFTER_LOAD, &NinjaMain::ToolTargets},
      {"compdb", "dump JSON compilation database to stdout",
       Tool::RUN_AFTER_LOAD, &NinjaMain::ToolCompilationDatabase},
      {"compdb-targets",
       "dump JSON compilation database for a given list of targets to stdout",
       Tool::RUN_AFTER_LOAD, &NinjaMain::ToolCompilationDatabaseForTargets},
      {"recompact", "recompacts ninja-internal data structures",
       Tool::RUN_AFTER_LOAD, &NinjaMain::ToolRecompact},
      {"restat", "restats all outputs in the build log", Tool::RUN_AFTER_FLAGS,
       &NinjaMain::ToolRestat},
      {"rules", "list all rules", Tool::RUN_AFTER_LOAD, &NinjaMain::ToolRules},
      {"cleandead",
       "clean built files that are no longer produced by the manifest",
       Tool::RUN_AFTER_LOGS, &NinjaMain::ToolCleanDead},
      {"urtle", nullptr, Tool::RUN_AFTER_FLAGS, &NinjaMain::ToolUrtle},
      {nullptr, nullptr, Tool::RUN_AFTER_FLAGS, nullptr}};

  if (tool_name == "list") {
    printf("ninja subtools:\n");
    for (const Tool* tool = &kTools[0]; tool->name; ++tool) {
      if (tool->desc)
        printf("%11s  %s\n", tool->name, tool->desc);
    }
    return nullptr;
  }

  for (const Tool* tool = &kTools[0]; tool->name; ++tool) {
    if (tool->name == tool_name)
      return tool;
  }

  std::vector<const char*> words;
  for (const Tool* tool = &kTools[0]; tool->name; ++tool)
    words.push_back(tool->name);
  const char* suggestion = SpellcheckStringV(tool_name, words);
  if (suggestion) {
    Fatal("unknown tool '%s', did you mean '%s'?", tool_name.c_str(),
          suggestion);
  } else {
    Fatal("unknown tool '%s'", tool_name.c_str());
  }
  return nullptr;  // Not reached.
}

/// Enable a debugging mode.  Returns false if Ninja should exit instead
/// of continuing.
bool DebugEnable(const std::string& name) {
  if (name == "list") {
    printf(
        "debugging modes:\n"
        "  stats        print operation counts/timing info\n"
        "  explain      explain what caused a command to execute\n"
        "  keepdepfile  don't delete depfiles after they're read by ninja\n"
        "  keeprsp      don't delete @response files on success\n"
        "multiple modes can be enabled via -d FOO -d BAR\n");
    return false;
  } else if (name == "stats") {
    g_metrics = new Metrics;
    return true;
  } else if (name == "explain") {
    g_explaining = true;
    return true;
  } else if (name == "keepdepfile") {
    g_keep_depfile = true;
    return true;
  } else if (name == "keeprsp") {
    g_keep_rsp = true;
    return true;
  } else if (name == "nostatcache") {
    g_experimental_statcache = false;
    return true;
  } else {
    const char* suggestion =
        SpellcheckString(name.c_str(), "stats", "explain", "keepdepfile",
                         "keeprsp", "nostatcache", nullptr);
    if (suggestion) {
      Error("unknown debug setting '%s', did you mean '%s'?", name.c_str(),
            suggestion);
    } else {
      Error("unknown debug setting '%s'", name.c_str());
    }
    return false;
  }
}

/// Set a warning flag.  Returns false if Ninja should exit instead of
/// continuing.
bool WarningEnable(const std::string& name, Options* options) {
  if (name == "list") {
    printf(
        "warning flags:\n"
        "  phonycycle={err,warn}  phony build statement references itself\n");
    return false;
  } else if (name == "dupbuild=err" || name == "dupbuild=warn") {
    Warning("deprecated warning 'dupbuild'");
    return true;
  } else if (name == "phonycycle=err") {
    options->phony_cycle_should_err = true;
    return true;
  } else if (name == "phonycycle=warn") {
    options->phony_cycle_should_err = false;
    return true;
  } else if (name == "depfilemulti=err" || name == "depfilemulti=warn") {
    Warning("deprecated warning 'depfilemulti'");
    return true;
  } else {
    const char* suggestion =
        SpellcheckString(name.c_str(), "dupbuild=err", "dupbuild=warn",
                         "phonycycle=err", "phonycycle=warn", nullptr);
    if (suggestion) {
      Error("unknown warning flag '%s', did you mean '%s'?", name.c_str(),
            suggestion);
    } else {
      Error("unknown warning flag '%s'", name.c_str());
    }
    return false;
  }
}

bool NinjaMain::OpenBuildLog(bool recompact_only) {
  std::string log_path = ".ninja_log";
  if (!build_dir_.empty())
    log_path = build_dir_ + "/" + log_path;

  std::string err;
  const LoadStatus status = build_log_.Load(log_path, &err);
  if (status == LOAD_ERROR) {
    Error("loading build log %s: %s", log_path.c_str(), err.c_str());
    return false;
  }
  if (!err.empty()) {
    // Load() can return a warning via err with LOAD_SUCCESS.
    Warning("%s", err.c_str());
    err.clear();
  }

  if (recompact_only) {
    if (status == LOAD_NOT_FOUND)
      return true;
    bool success = build_log_.Recompact(log_path, *this, &err);
    if (!success)
      Error("failed recompaction: %s", err.c_str());
    return success;
  }

  if (!config_.dry_run) {
    if (!build_log_.OpenForWrite(log_path, *this, &err)) {
      Error("opening build log: %s", err.c_str());
      return false;
    }
  }

  return true;
}

bool NinjaMain::OpenDepsLog(bool recompact_only) {
  std::string path = ".ninja_deps";
  if (!build_dir_.empty())
    path = build_dir_ + "/" + path;

  std::string err;
  const LoadStatus status = deps_log_.Load(path, &state_, &err);
  if (status == LOAD_ERROR) {
    Error("loading deps log %s: %s", path.c_str(), err.c_str());
    return false;
  }
  if (!err.empty()) {
    // Load() can return a warning via err with LOAD_SUCCESS.
    Warning("%s", err.c_str());
    err.clear();
  }

  if (recompact_only) {
    if (status == LOAD_NOT_FOUND)
      return true;
    bool success = deps_log_.Recompact(path, &err);
    if (!success)
      Error("failed recompaction: %s", err.c_str());
    return success;
  }

  if (!config_.dry_run) {
    if (!deps_log_.OpenForWrite(path, &err)) {
      Error("opening deps log: %s", err.c_str());
      return false;
    }
  }

  return true;
}

void NinjaMain::DumpMetrics() {
  g_metrics->Report();

  printf("\n");
  int count = (int)state_.paths_.size();
  int buckets = (int)PathTableBucketCount(state_.paths_.size());
  printf("path->node hash load %.2f (%d entries / %d buckets)\n",
         count / (double)buckets, count, buckets);
}

bool NinjaMain::EnsureBuildDirExists() {
  build_dir_ = state_.bindings_.LookupVariable("builddir");
  if (!build_dir_.empty() && !config_.dry_run) {
    if (!disk_interface_.MakeDirs(build_dir_ + "/.") && errno != EEXIST) {
      Error("creating build directory %s: %s", build_dir_.c_str(),
            strerror(errno));
      return false;
    }
  }
  return true;
}

ExitStatus NinjaMain::RunBuild(int argc, char** argv, Status* status) {
  std::string err;
  std::vector<Node*> targets;
  if (!CollectTargetsFromArgs(argc, argv, &targets, &err)) {
    status->Error("%s", err.c_str());
    return ExitFailure;
  }

  disk_interface_.AllowStatCache(g_experimental_statcache);

  // Use the GNU make jobserver if MAKEFLAGS describes one.
  std::unique_ptr<JobserverClient> jobserver_client;
  if (!config_.dry_run && !config_.disable_jobserver_client) {
    const char* makeflags = getenv("MAKEFLAGS");
    if (makeflags) {
      JobserverConfig jobserver_config;
      std::string parse_err;
      if (!ParseJobserverMakeFlags(makeflags, &jobserver_config, &parse_err)) {
        status->Warning("Ignoring jobserver: %s [%s]", parse_err.c_str(),
                        makeflags);
      } else if (jobserver_config.mode == JobserverConfig::kModePipe) {
        status->Warning(
            "Ignoring jobserver: Pipe-based protocol is not supported! [%s]",
            makeflags);
      } else if (jobserver_config.mode ==
                 JobserverConfig::kModeWin32Semaphore) {
        status->Warning(
            "Ignoring jobserver: Semaphore mode is not supported on Posix! "
            "[%s]",
            makeflags);
      } else if (jobserver_config.mode == JobserverConfig::kModePosixFifo) {
        if (config_.verbosity > BuildConfig::NO_STATUS_UPDATE)
          status->Info("Jobserver mode detected: %s", makeflags);
        std::string client_err;
        jobserver_client.reset(
            JobserverClient::Create(jobserver_config, &client_err));
        if (!jobserver_client)
          status->Error("Could not initialize jobserver: %s",
                        client_err.c_str());
      }
    }
  }

  Builder builder(&state_, config_, &build_log_, &deps_log_, &disk_interface_,
                  status, start_time_millis_);
  if (jobserver_client)
    builder.SetJobserverClient(jobserver_client.get());

  for (Node* target : targets) {
    if (!builder.AddTarget(target, &err)) {
      if (!err.empty()) {
        status->Error("%s", err.c_str());
        return ExitFailure;
      } else {
        // Added a target that is already up-to-date; not really an error.
      }
    }
  }

  // Make sure restat rules do not see stale timestamps.
  disk_interface_.AllowStatCache(false);

  if (builder.AlreadyUpToDate()) {
    if (config_.verbosity != BuildConfig::NO_STATUS_UPDATE)
      status->Info("no work to do.");
    return ExitSuccess;
  }

  ExitStatus exit_status = builder.Build(&err);
  if (exit_status != ExitSuccess) {
    status->Info("build stopped: %s.", err.c_str());
    if (err.find("interrupted by user") != std::string::npos)
      return ExitInterrupted;
  }

  return exit_status;
}

/// Parse argv for command-line options.
/// Returns an exit code, or -1 if Ninja should continue.
int ReadFlags(int* argc, char*** argv, Options* options, BuildConfig* config) {
  bool need_guess = true;

  enum { OPT_VERSION = 1, OPT_QUIET = 2 };
  const option kLongOptions[] = {{"help", no_argument, nullptr, 'h'},
                                 {"version", no_argument, nullptr, OPT_VERSION},
                                 {"verbose", no_argument, nullptr, 'v'},
                                 {"quiet", no_argument, nullptr, OPT_QUIET},
                                 {nullptr, 0, nullptr, 0}};

  int opt;
  while (!options->tool &&
         (opt = getopt_long(*argc, *argv, "d:f:j:k:l:nt:vw:C:h", kLongOptions,
                            nullptr)) != -1) {
    switch (opt) {
      case 'd':
        if (!DebugEnable(optarg))
          return 1;
        break;
      case 'f':
        options->input_file = optarg;
        break;
      case 'j': {
        char* end;
        long value = strtol(optarg, &end, 10);
        if (*end != 0 || value < 0)
          Fatal("invalid -j parameter");

        // For -j0, INT_MAX is close enough to infinite.
        config->parallelism = value > 0 ? (int)value : INT_MAX;
        config->disable_jobserver_client = true;
        need_guess = false;
        break;
      }
      case 'k': {
        char* end;
        long value = strtol(optarg, &end, 10);
        if (*end != 0)
          Fatal("-k parameter not numeric; did you mean -k 0?");

        // Allow N failures; N <= 0 means "infinitely many".
        config->failures_allowed = value > 0 ? (int)value : INT_MAX;
        break;
      }
      case 'l': {
        char* end;
        double value = strtod(optarg, &end);
        if (end == optarg)
          Fatal("-l parameter not numeric: did you mean -l 0.0?");
        config->max_load_average = value;
        break;
      }
      case 'n':
        config->dry_run = true;
        break;
      case 't':
        options->tool = ChooseTool(optarg);
        if (!options->tool)
          return 0;
        break;
      case 'v':
        config->verbosity = BuildConfig::VERBOSE;
        break;
      case OPT_QUIET:
        config->verbosity = BuildConfig::NO_STATUS_UPDATE;
        break;
      case 'w':
        if (!WarningEnable(optarg, options))
          return 1;
        break;
      case 'C':
        options->working_dir = optarg;
        break;
      case OPT_VERSION:
        printf("%s\n", kNinjaVersion);
        return 0;
      case 'h':
      default:
        if (need_guess) {
          need_guess = false;
          config->parallelism = GuessParallelism();
        }
        Usage(*config);
        return 1;
    }
  }
  *argv += optind;
  *argc -= optind;

  if (need_guess)
    config->parallelism = GuessParallelism();

  return -1;
}

[[noreturn]] void real_main(int argc, char** argv) {
  // exit() is used throughout instead of return, to skip expensive cleanup.
  BuildConfig config;
  Options options;
  options.input_file = "build.ninja";

  setvbuf(stdout, nullptr, _IOLBF, BUFSIZ);
  const char* ninja_command = argv[0];

  int exit_code = ReadFlags(&argc, &argv, &options, &config);
  if (exit_code >= 0)
    exit(exit_code);

  Status* status = Status::factory(config);

  if (options.working_dir) {
    // The quoting in this message lets Emacs track the directory change.
    // Not printed for tools so their output can be piped cleanly.
    if (!options.tool && config.verbosity != BuildConfig::NO_STATUS_UPDATE)
      status->Info("Entering directory `%s'", options.working_dir);
    if (chdir(options.working_dir) < 0) {
      Fatal("chdir to '%s' - %s", options.working_dir, strerror(errno));
    }
  }

  if (options.tool && options.tool->when == Tool::RUN_AFTER_FLAGS) {
    // These tools don't need a loaded manifest.
    NinjaMain ninja(ninja_command, config);
    exit((ninja.*options.tool->func)(&options, argc, argv));
  }

  // Limit number of rebuilds, to prevent infinite loops.
  const int kCycleLimit = 100;
  for (int cycle = 1; cycle <= kCycleLimit; ++cycle) {
    NinjaMain ninja(ninja_command, config);

    ManifestParserOptions parser_opts;
    if (options.phony_cycle_should_err)
      parser_opts.phony_cycle_action_ = kPhonyCycleActionError;
    ManifestParser parser(&ninja.state_, &ninja.disk_interface_, parser_opts);
    std::string err;
    if (!parser.Load(options.input_file, &err)) {
      status->Error("%s", err.c_str());
      exit(1);
    }

    if (options.tool && options.tool->when == Tool::RUN_AFTER_LOAD)
      exit((ninja.*options.tool->func)(&options, argc, argv));

    if (!ninja.EnsureBuildDirExists())
      exit(1);

    if (!ninja.OpenBuildLog() || !ninja.OpenDepsLog())
      exit(1);

    if (options.tool && options.tool->when == Tool::RUN_AFTER_LOGS)
      exit((ninja.*options.tool->func)(&options, argc, argv));

    // Attempt to rebuild the manifest before building anything else.
    if (ninja.RebuildManifest(options.input_file, &err, status)) {
      // In dry run mode the manifest won't change, so stop here.
      if (config.dry_run)
        exit(0);
      // Start the build over with the new manifest.
      continue;
    } else if (!err.empty()) {
      status->Error("rebuilding '%s': %s", options.input_file, err.c_str());
      exit(1);
    }

    ninja.ParsePreviousElapsedTimes();

    ExitStatus result = ninja.RunBuild(argc, argv, status);
    if (g_metrics)
      ninja.DumpMetrics();
    exit(result);
  }

  status->Error(
      "manifest '%s' still dirty after %d tries, perhaps system time is not "
      "set",
      options.input_file, kCycleLimit);
  exit(1);
}

}  // anonymous namespace

int main(int argc, char** argv) { real_main(argc, argv); }
